const top_tryndamere = {
  champion: '트린다미어',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 빠르게 접근해 침묵을 걸면 (E)\'회전 베기\'나 (Q)\'피의 갈망\'을 쓰지 못하게 방해해요. 1~2레벨에는 평타로 분노를 쌓으며 (Q)\'결정타\'가 빠질 때까지 거리를 조절하고, 가렌의 (P)\'인내심\' 회복이 돌지 않게 짧게 평타를 섞어주세요. (Q)\'결정타\'를 맞기 전까지는 무리하게 붙지 말고 웨이브를 관리하며 기회를 보세요.', lv3: '가렌이 (Q)\'결정타\'로 진입할 때 (W)\'조롱의 외침\'을 사용해 공격력을 낮추고, 가렌이 등을 돌려 도망갈 때 둔화를 걸어 추격하세요. (W)\'용기\' 보호막이 켜져 있을 때는 (E)\'회전 베기\'로 짧게 딜교환만 하고, 보호막과 피해 감소 효과가 끝난 뒤에 본격적으로 공격하세요. (E)\'심판\' 회전이 시작되면 빠르게 거리를 벌리거나 (Q)\'피의 갈망\'으로 체력을 관리하며 버티세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 체력이 낮을 때 치명적이니, 이를 (R)\'불사의 분노\'로 무시하며 역공을 가하는 것이 중요해요. 가렌이 (W)\'용기\'와 (E)\'심판\'을 모두 사용한 타이밍에 (E)\'회전 베기\'로 진입해 끝까지 추격하며 딜교환을 이어가세요. 정글러가 올 때는 가렌이 (Q)\'결정타\'로 빠르게 도망갈 수 있으니 라인을 적절히 밀어 두고 호응하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수로 유지력을 높이세요. 신발은 가렌의 기본 공격 피해를 줄여 주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 가렌의 (P)\'인내심\' 회복을 막아야 킬각을 잡기 훨씬 쉬워요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 골드를 챙기며 괴롭히지만 근접전은 약한 편이에요. (Q)\'혀어어어업상\'에 맞지 않도록 거리를 조절하며 미니언을 챙기세요. (Q)\'피의 갈망\'으로 체력을 회복하며 버티고 기회를 보세요.', lv3: '갱플랭크가 설치한 (E)\'화약통\' 근처에서 싸우면 폭발로 인해 둔화를 맞을 수 있으니 주의하세요. (E)\'회전 베기\'를 사용해 진입할 때 갱플랭크의 (W)\'괴혈병 치료\'가 빠졌는지 확인하고 싸우는 것이 좋아요. (W)\'조롱의 외침\'으로 상대 공격력을 낮추며 딜교환을 이어가세요.', lv6: '(R)\'불사의 분노\'를 사용하면 죽지 않고 버틸 수 있으니 갱플랭크의 (E)\'화약통\' 폭발을 무시하며 몰아붙이세요. 갱플랭크가 (R)\'포탄 세례\'를 사용해 광역 둔화를 걸면 추격이 어려워지니 장판이 깔리기 전에 승부를 보세요. 라인을 빠르게 밀어 넣고 갱플랭크가 (Q)\'혀어어어업상\'으로 골드를 못 챙기게 압박하세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 갱플랭크의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화를 사용하면 갱플랭크의 (W)\'괴혈병 치료\'로 인한 체력 회복을 억제하는 데 도움이 돼요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고 (P)\'서비스 시간\'으로 체력을 계속 회복해요. 술통의 폭발 위치를 피해 거리 조절을 하다가 (E)\'회전 베기\'로 빠르게 진입해 평타를 입히세요. 초반 소모전에서는 무리하게 붙지 말고 분노를 쌓으며 기회를 보세요.', lv3: '(E)\'몸통 박치기\'의 공중 띄우기에 맞으면 딜교환이 힘드니 그라가스가 돌진하기 전까지는 거리를 유지하세요. (W)\'취중 분노\'가 켜진 동안은 받는 피해가 줄어드니 잠시 기다렸다가 (W)\'조롱의 외침\'을 써서 공격력을 낮추고 추격하세요. 체력이 낮아졌을 때는 (Q)\'피의 갈망\'으로 체력을 회복하며 끈질기게 버티는 것이 중요해요.', lv6: '(R)\'술통 폭발\'에 밀려나면 추격 흐름이 끊기니 상대의 궁극기 위치를 잘 살피세요. (R)\'불사의 분노\'를 켜고 진입하면 그라가스의 폭발적인 피해를 무시하며 강하게 밀어붙일 수 있어요. 라인을 밀어두고 정글 개입을 대비하며 (E)\'회전 베기\'로 빠르게 합류하거나 빠져나가세요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수로 그라가스와 오래 교환하세요. 신발은 마법 저항력과 강인함을 줘서 (Q)\'술통 굴리기\'의 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'의 회복을 방해하고 낮은 체력의 그라가스를 확실히 마무리하기 좋기 때문이에요.' },
    '그웬': { lv1: '그웬은 (P)\'가위 난도질\'의 체력 비례 피해와 회복 덕에 근접전에서 강한 모습을 보여요. (Q)\'싹둑싹둑!\'의 중앙 고정 피해를 피하며 (E)\'회전 베기\'로 빠르게 분노를 쌓고 짧게 치고 빠지세요. 무리하게 붙어 있다가 가위질을 모두 맞으면 체력이 금방 깎이니 주의하세요.', lv3: '(W)\'신성한 안개\'가 켜져 있어도 (E)\'회전 베기\'나 (W)\'조롱의 외침\' 같은 범위 공격은 그대로 들어가요. 그웬이 (E)\'돌격가위\'로 거리를 조절하며 때리려 할 때 (W)\'조롱의 외침\'으로 공격력을 낮추고 둔화를 거세요. (Q)\'싹둑싹둑!\'의 횟수가 적을 때 진입해 공격하고 (Q)\'피의 갈망\'으로 체력을 관리하세요.', lv6: '(R)\'바느질\'의 둔화와 피해가 강력하므로 체력이 낮을 때 (R)\'불사의 분노\'를 켜고 과감하게 진입하세요. (W)\'신성한 안개\' 밖에서는 평타를 칠 수 없으니 안개 속으로 빠르게 들어가서 공격해야 해요. (E)\'회전 베기\'로 빠르게 접근해 상대의 바늘이 모두 빠진 뒤에 딜교환을 마무리하세요.', item: '맬모셔스의 아귀를 첫 코어로 선택해 마법 저항력을 높이고 체력이 낮을 때 보호막을 얻으세요. 신발은 (R)\'바느질\'의 둔화 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'가위 난도질\'의 체력 회복력을 억제해야 킬각을 잡기 편해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 멀리서 둔화를 걸며 견제하니 무리하게 맞서기보다 미니언 근처에서 체력을 관리하며 버티세요. (E)\'회전 베기\'로 미니언을 쳐서 분노를 모으며 나르의 공격 궤적을 피하는 것이 좋아요.', lv3: '나르의 분노가 차서 메가 나르로 변신하면 (W)\'쿵쾅\'의 기절을 조심하며 거리를 유지하세요. 미니 나르 상태일 때 (W)\'조롱의 외침\'으로 나르의 공격력을 낮추고 (E)\'회전 베기\'로 접근하여 짧게 딜교환을 하세요.', lv6: '메가 나르가 (R)\'나르!\'를 써서 벽에 부딪히면 기절하니 벽 근처에서의 교전은 피하는 것이 안전해요. 나르의 강력한 공격을 (R)\'불사의 분노\'로 버텨내며 역습을 시도하여 전투를 이끌어 가세요.', item: '몰락한 왕의 검을 첫 코어로 올려 지속 싸움 능력을 키우세요. 신발은 나르의 (W)\'쿵쾅\'이나 (R)\'나르!\'의 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 증가와 유닛 충돌 무시로 나르의 (E)\'폴짝\' 이후 움직임을 따라잡기 쉬워요.' },
    '나서스': { lv1: '나서스가 (Q)\'흡수의 일격\'으로 미니언 막타를 치며 성장하지 못하도록 (E)\'회전 베기\'로 꾸준히 견제하세요. 초반에는 몸싸움이 가능하니 적극적으로 움직이되 (Q)\'피의 갈망\'을 사용해 체력을 관리하며 거리를 조절해요. 미니언 사이에서 나서스의 (Q)\'흡수의 일격\'에 맞지 않도록 주의하며 압박을 이어가세요.', lv3: '나서스의 (W)\'쇠약\'에 걸리면 이동 속도와 공격 속도가 함께 감소하니 효과가 완전히 끝날 때까지 기다렸다가 교환하세요. (E)\'영혼의 불길\' 장판 위에서는 방어력이 낮아져 피해가 커지므로 그 범위 안에서 싸우지 않도록 주의해요. (W)\'조롱의 외침\'을 사용해 나서스의 공격력을 낮추며 짧게 딜교환을 하고 빠지는 것이 좋아요.', lv6: '나서스가 (R)\'사막의 분노\'를 켜면 체력과 공격 범위가 늘어나니 무리하게 붙지 말고 거리를 유지하세요. 나서스의 궁극기 지속시간 동안은 (R)\'불사의 분노\'를 사용하여 버티며 상대 스킬이 빠진 뒤에 승부를 보세요. 라인을 빠르게 밀어 넣어 나서스가 (Q)\'흡수의 일격\' 중첩을 쌓을 시간을 최대한 뺏어야 해요.', item: '체력이 높은 나서스를 상대하기 위해 몰락한 왕의 검을 첫 코어로 가고 생명력 흡수를 챙기세요. 신발은 나서스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 체력 회복 효과를 감소시키며 승부를 보세요.' },
    '녹턴': { lv1: '1~2레벨에는 (Q)\'황혼의 인도자\'를 피하며 거리를 조절하세요. 상대의 (P)\'그림자 칼날\' 평타를 맞지 않도록 주의하며 (E)\'회전 베기\'로 미니언을 챙겨야 해요. 상대가 궤적 위에서 이동 속도를 얻는 구간을 경계하세요.', lv3: '3레벨에는 (E)\'말할 수 없는 공포\'의 연결 범위에서 벗어나 공포에 빠지지 않도록 거리를 조절하며 딜교환을 해요. 상대의 (W)\'어둠의 장막\'은 내 다음 스킬을 막아주니 보호막이 사라진 것을 확인한 뒤 (E)\'회전 베기\'로 진입하세요. 그 뒤 (W)\'조롱의 외침\'으로 상대의 공격력을 낮추는 것이 좋아요.', lv6: '6레벨 이후에는 상대의 (R)\'피해망상\' 돌격에 대비해 (R)\'불사의 분노\'를 상황에 맞춰 사용하세요. 시야가 좁아지는 시점에는 정글의 개입을 조심하며 라인을 관리해야 해요. 상대의 공포 효과가 발동하기 전에 거리를 조절하는 것이 중요해요.', item: '판금 장화와 몰락한 왕의 검을 선택하세요. 상대의 기본 공격 피해를 줄이고 생명력 흡수를 얻기 위해 선택해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소로 (P)\'그림자 칼날\'의 체력 회복을 줄이고 마무리 피해도 챙기세요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩과 (Q)\'학살\'의 체력 회복으로 초반 근접전에서 앞서가요. (E)\'회전 베기\'로 짧게 피해를 주고 빠르게 빠지는 식으로 체력을 깎으세요. (Q)\'학살\'의 도끼날 범위에 맞으면 다리우스가 체력을 회복하니 도끼자루 쪽으로 붙거나 완전히 피해야 해요.', lv3: '(E)\'포획\'에 끌려가 (W)\'마비의 일격\' 둔화까지 맞으면 위험하니 거리 조절에 신경 쓰세요. (E)\'포획\'이 빠진 것을 확인하고 (E)\'회전 베기\'로 진입해 짧게 몰아치세요. (W)\'조롱의 외침\'으로 다리우스의 공격력을 낮추고 (Q)\'피의 갈망\'으로 체력을 관리하며 끈질기게 괴롭히세요.', lv6: '(R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 높을 때 매우 아프니 중첩이 쌓이기 전에 승부를 보세요. 체력이 낮아져 위험한 순간에 (R)\'불사의 분노\'를 켜면 다리우스의 궁극기 피해를 버티며 역전할 수 있어요. (E)\'포획\'이 빠진 타이밍을 노려 공격하고 정글러가 오기 편하게 라인을 관리하세요.', item: '판금 장화는 다리우스의 기본 공격 피해를 줄여 줘요. 크라켄 학살자를 첫 코어로 선택해 공격 속도와 물리 피해를 높여 빠르게 적을 제압하세요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'포획\' 사거리 밖에서 움직이며 딜교환 각을 잡거나 위험할 때 빠르게 도망치세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 직선으로 발사해 견제하는데, 첫 번째 맞는 적에게만 피해를 주니 미니언 뒤에 숨어서 최대한 덜 맞으세요. 초반에는 무리하게 붙기보다 미니언을 챙기며 (Q)\'피의 갈망\'으로 체력을 회복하며 버티는 것이 중요해요. 라이즈의 마나가 많이 빠질 때까지 거리를 조절하세요.', lv3: '(E)\'주문 전이\' 표식이 남은 상태에서 (W)\'룬 감옥\'을 맞으면 속박되니, 표식이 붙었을 때는 잠시 뒤로 빠지세요. (W)\'룬 감옥\'이 빠진 것을 확인한 뒤 (E)\'회전 베기\'로 진입해 (W)\'조롱의 외침\'을 사용하면 라이즈가 도망갈 때 둔화되어 계속 추격할 수 있어요. 스킬 쿨타임을 계산해 진입 시점을 잡으세요.', lv6: '(R)\'불사의 분노\'를 켜면 라이즈의 강력한 주문 피해를 버티며 끝까지 추격해 킬을 낼 수 있어요. 라이즈가 (R)\'공간 왜곡\'으로 아군과 함께 이동하거나 합류할 수 있으니, 정글러의 위치를 확인하고 무리하게 라인을 밀지 마세요. (E)\'회전 베기\'로 순식간에 거리를 좁혀 라이즈의 체력을 깎으세요.', item: '크라켄 학살자를 첫 코어로 선택해 강력한 공격 속도와 피해량을 확보하세요. 신발은 헤르메스의 발걸음을 신어 마법 저항력을 높이고 (W)\'룬 감옥\'의 속박 지속 시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해로 (W)\'룬 감옥\'과 (Q)\'과부하\'를 주고받은 뒤 마무리하기 좋아요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 사용하여 근접한 적에게 마법 피해를 입히며 라인을 밀어요. (Q)\'화염방사기\'의 원뿔 범위 가장자리에 서서 피해를 최소화하며 미니언을 챙기세요. (E)\'회전 베기\'로 미니언을 맞춰 분노를 미리 쌓아두는 것이 좋아요.', lv3: '럼블이 (E)\'전기 작살\'을 맞히면 이동 속도가 느려지고 마법 저항력이 감소하니 주의해야 해요. 럼블이 (W)\'고철 방패\'를 사용해 피해를 흡수할 때는 무리하게 싸우지 말고 (W)\'조롱의 외침\'으로 공격력을 낮추며 기회를 보세요. (Q)\'피의 갈망\'으로 체력을 회복하며 짧게 딜교환을 진행하세요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 사용해 장판을 깔면 그 위에서 싸우지 말고 즉시 벗어나야 해요. 체력이 낮아지면 (R)\'불사의 분노\'를 사용해 럼블의 마법 피해를 버티며 역전의 발판을 만드세요. 럼블은 궁극기를 활용한 갱킹 호응이 강력하니 라인을 밀 때 항상 조심하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 헤르메스의 발걸음은 마법 저항력을 제공하며 몰락한 왕의 검은 전투 지속력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 럼블의 체력을 깎아 킬각을 잡기에 좋아요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해를 입히며 체력을 회복하므로 1~2레벨에는 정면 충돌을 피하세요. (E)\'회전 베기\'를 사용해 분노를 쌓으며 미니언을 챙기고, 레넥톤의 분노가 쌓여 강화된 공격이 들어오기 전까지 거리를 조절해요. 상대의 공격 사거리를 벗어나 체력 소모를 최소화하며 신중하게 행동하세요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 빠르게 진입할 때 (W)\'조롱의 외침\'을 써서 상대의 공격력을 낮추세요. (W)\'무자비한 포식자\'의 기절 효과가 빠진 것을 확인한 뒤 (E)\'회전 베기\'로 진입해 짧게 딜교환을 하고 빠지세요. 분노가 가득 찬 레넥톤의 강화 기절은 매우 아프니 분노 게이지를 확인하며 거리 조절을 해요.', lv6: '(R)\'강신\'을 켠 레넥톤은 체력이 많고 분노가 빠르게 차오르니 정면 승부보다는 시간을 끄세요. 상대의 폭발적인 피해가 들어오는 타이밍에 (R)\'불사의 분노\'를 켜서 버티고, (Q)\'피의 갈망\'으로 소모한 체력을 회복하며 역공을 노리세요. 레넥톤이 (E)\'자르고 토막내기\'로 도망치려 할 때 끝까지 추격해 피해를 입히는 것이 중요해요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력 비례 피해와 생명력 흡수로 지속 싸움 능력을 높이세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 레넥톤의 (Q)\'양떼 도륙\' 회복량을 억제해야 킬각을 잡기 쉬워요.' },
    '렝가': { lv1: '수풀 근처에서 (P)\'보이지 않는 포식자\'를 통해 도약하는 것을 경계해야 해요. 첫 웨이브를 빠르게 정리하며 (E)\'회전 베기\'로 분노를 쌓고 거리를 유지하세요. 상대가 강하게 들어오는 구간에는 무리하게 맞서지 마세요.', lv3: '상대가 (E)\'올가미 투척\'을 사용하면 맞서 싸우지 말고 거리를 벌려야 해요. (E)\'올가미 투척\'이 빠진 것을 확인한 뒤에 (E)\'회전 베기\'를 활용해 딜교환을 시도하세요. (Q)\'피의 갈망\'으로 체력을 관리하며 전투를 준비하세요.', lv6: '(R)\'사냥의 전율\'을 사용해 들어오는 타이밍에 (R)\'불사의 분노\'를 사용하세요. 상대의 방어력 감소 효과를 주의하며 라인을 밀어넣어 정글의 개입을 대비해야 해요. 수풀 위치를 항상 확인하며 싸우는 것이 좋아요.', item: '판금 장화와 몰락한 왕의 검을 가세요. 판금 장화는 상대의 기본 공격 피해를 줄여주며 몰락한 왕의 검은 전투 지속력을 높여줘요.', spell: '점멸과 유체화를 선택하세요. 점멸로 상대의 접근을 피하고 유체화로 거리를 조절하며 전투를 이끌기 위해서예요.' },
    '리븐': { lv1: '리븐이 (Q)\'부러진 날개\'로 들어오며 (P)\'룬 검\' 평타를 섞을 때 거리를 조절하며 대응하세요. 1~2레벨에는 무리하게 맞붙기보다 (E)\'회전 베기\'로 미니언을 챙기며 리븐의 진입을 경계해야 해요. 리븐의 돌진 사거리 안으로 너무 깊게 들어가지 않도록 주의하세요.', lv3: '리븐이 (W)\'기 폭발\'로 기절을 시도할 때 (W)\'조롱의 외침\'을 사용하여 공격력을 낮추고 둔화를 거는 것이 중요해요. 리븐의 (E)\'용맹\' 보호막이 유지되는 동안에는 (E)\'회전 베기\'로 딜교환을 하기보다 뒤로 물러나 타이밍을 보세요. 리븐이 (Q)\'부러진 날개\' 세 번째 타격으로 밀쳐내기 전에 거리를 잡아야 해요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜고 공격 사거리가 늘어난 상태라면 체력이 낮을 때 멀리 떨어지세요. 리븐의 강력한 연계가 들어올 때 (R)\'불사의 분노\'를 사용하여 버티면서 역습을 노리면 킬을 가져오기 좋아요. 리븐이 궁극기를 활용해 압박할 때는 라인을 당겨서 정글의 도움을 받으세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 리븐의 (P)\'룬 검\' 평타처럼 기본 공격으로 받는 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 리븐의 체력이 낮아졌을 때 점화로 확실하게 마무리하세요.' },
    '리산드라': { lv1: '(Q)\'얼음 파편\'은 미니언을 꿰뚫고 날아와 둔화를 걸기 때문에 미니언 뒤에 숨어도 맞으니 주의하세요. 1~2레벨에는 무리하게 붙지 말고 평타로 분노를 쌓으며 체력을 관리하세요. 상대가 막타를 치러 오는 타이밍에 (E)\'회전 베기\'로 빠르게 접근해 평타 딜교환을 하세요.', lv3: '(W)\'서릿발\'에 묶여도 공격은 가능하니 당황하지 말고 평타를 넣으세요. 리산드라가 (E)\'얼음갈퀴 길\'로 순간이동하며 거리를 벌리면 (W)\'조롱의 외침\'으로 둔화를 걸어 추격하세요. (E)\'회전 베기\'는 상대의 (W)\'서릿발\'이 빠진 것을 확인한 뒤에 진입해야 묶이지 않고 딜을 넣을 수 있어요.', lv6: '리산드라가 (R)\'얼음 무덤\'으로 기절시키면 정글러의 개입이 쉬우니 주변 시야를 꼭 확인하세요. 기절 중에는 스킬을 쓸 수 없으니 (R)\'불사의 분노\'는 (R)\'얼음 무덤\'을 맞기 전에 미리 켜 두세요. 상대가 자신에게 (R)\'얼음 무덤\'을 써서 무적이 되면 공격을 멈추고 거리 조절을 하세요.', item: '마법사의 최후를 가서 마법 저항력과 공격 속도를 챙기세요. 신발은 (W)\'서릿발\'의 속박과 (R)\'얼음 무덤\'의 기절 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. (W)\'서릿발\'의 속박이나 (R)\'얼음 무덤\'의 기절을 정화로 즉시 풀고 (E)\'회전 베기\'로 다시 진입할 수 있어요.' },
    '마스터이': { lv1: '1~2레벨에는 마스터 이가 (P)\'2연속 공격\'과 (E)\'우주류 검술\'의 고정 피해로 평타 교환이 강해요. 무리하게 붙지 말고 (E)\'회전 베기\'로 미니언과 함께 피해를 주며 분노를 쌓으세요. 거리 조절을 하며 상대의 체력을 깎아두는 것이 중요해요.', lv3: '마스터 이가 (Q)\'일격 필살\'로 진입한 직후에 (W)\'조롱의 외침\'을 써서 공격력을 낮추고, 상대가 등을 돌려 빠질 때 둔화로 추격하세요. (W)\'명상\'으로 체력을 회복할 때는 억지로 공격하지 말고 (Q)\'피의 갈망\'으로 자신의 체력을 관리하며 기회를 보세요. (Q)\'일격 필살\'이 빠진 상태에서 (E)\'회전 베기\'로 붙으면 상대가 도망치기 어려워요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 켜면 둔화에 면역이라 (W)\'조롱의 외침\'의 이동 속도 감소가 통하지 않아요. 하지만 (R)\'불사의 분노\'를 켜면 상대의 폭발적인 공격을 견디며 역으로 처치할 수 있어요. 정글러가 개입할 때 마스터 이가 (Q)\'일격 필살\'로 빠르게 진입해 킬을 챙기지 않도록 주의하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수를 챙기세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복하는 것을 점화로 방해해야 확실하게 잡을 수 있어요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 밀어내며 둔화를 걸고 기본 공격 시 (P)\'마법 흡수\'로 체력을 회복하며 압박해요. 1~2레벨에는 무리하게 붙기보다 마오카이가 (Q)\'덤불 주먹\'을 헛치게 유도하고 평타로 분노를 쌓으며 짧게 교환하세요. (Q)\'피의 갈망\'을 사용해 체력을 관리하며 상대의 초반 견제를 최대한 받아내세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 도약해 속박할 때는 대상으로 지정할 수 없으니, 이 스킬이 빠진 것을 확인한 뒤 (E)\'회전 베기\'로 진입하세요. (E)\'묘목 던지기\'가 깔린 수풀은 피하고, 속박 중에도 평타와 (W)\'조롱의 외침\'은 쓸 수 있으니 공격을 이어가다 마오카이가 등을 돌리면 둔화로 추격하세요. (Q)\'피의 갈망\'으로 회복하며 상대의 스킬 쿨타임을 이용해 딜교환을 이어가세요.', lv6: '(R)\'대자연의 마수\'의 거대한 벽은 천천히 전진하며 닿은 적을 속박하니, 벽의 경로를 잘 보고 옆으로 피해 주세요. 마오카이가 벽을 쓴 직후 (R)\'불사의 분노\'를 켜고 진입하면 (W)\'뒤틀린 전진\'에 속박되더라도 죽지 않고 끝까지 공격할 수 있어요. 정글러가 (W)\'뒤틀린 전진\'이나 벽으로 호응하기 좋으니 라인 관리와 시야 확보에 신경 쓰세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 마오카이에게 더 많은 피해를 입히세요. 신발은 헤르메스의 발걸음을 선택해 속박과 둔화 같은 군중 제어 지속시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 마오카이가 (P)\'마법 흡수\'로 체력을 계속 회복하므로 점화의 치유 감소 효과로 이를 억제하며 킬각을 잡으세요.' },
    '말자하': { lv1: '말자하는 (P)\'공허 태세\' 덕분에 초반에 피해를 적게 받으니 (E)\'회전 베기\'를 사용해서 이 보호 효과를 먼저 제거하세요. (Q)\'공허의 부름\' 투사체에 맞으면 침묵에 걸려 스킬 사용이 제한될 수 있으니 주의하며 거리 조절을 해야 해요. (Q)\'피의 갈망\'으로 체력을 관리하며 1~2레벨 동안 꾸준히 압박하세요.', lv3: '말자하가 (E)\'재앙의 환상\'을 걸고 (W)\'공허의 무리\'를 소환하면 공허충들의 공격이 부담스러우니 주의해야 해요. (W)\'조롱의 외침\'을 사용하여 말자하의 공격력을 낮추고 진입하는 것이 좋아요. (Q)\'공허의 부름\'에 침묵을 당하더라도 평타는 계속 사용할 수 있으니 당황하지 마세요.', lv6: '(R)\'황천의 손아귀\'에 제압당하면 스킬과 점멸을 쓸 수 없으니 (R)\'불사의 분노\'는 걸리기 전에 미리 켜 두세요. 말자하가 (E)\'재앙의 환상\'을 묻힌 상태에서 공허충들이 몰려오면 위험하니 무리하게 들어가지 마세요. 상대 정글러가 근처에 있다면 제압당할 때 바로 잡힐 수 있으니 조심하세요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 가세요. 몰락한 왕의 검은 생명력 흡수를 제공하고 헤르메스의 발걸음은 마법 저항력과 강인함을 줘요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 점화로 마무리하는 것이 좋아요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 체력을 깎고 이동 속도를 훔치는데, 대상 지정 스킬이라 미니언 뒤에 숨어도 맞으니 조심하세요. (P)\'화강암 방패\'가 활성화되어 있을 때는 평타 교환이 손해이므로, (E)\'회전 베기\'로 빠르게 접근해 방패를 먼저 벗겨내세요. 방패가 사라진 틈을 타 짧게 공격하고 (Q)\'피의 갈망\'으로 체력을 관리하며 버티세요.', lv3: '(E)\'지면 강타\'를 맞으면 공격 속도가 크게 낮아지니, 이 스킬이 빠진 것을 확인하고 (E)\'회전 베기\'로 진입하세요. 말파이트가 (W)\'천둥소리\'를 켜고 공격하면 피해가 크므로 (W)\'조롱의 외침\'으로 공격력을 낮추고, 말파이트가 물러날 때는 둔화로 추격하세요. 공격 속도 감소 효과가 없을 때 몰아쳐야 (Q)\'피의 갈망\'의 효율을 높이며 딜교환을 이끌 수 있어요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 막을 수 없고, 공중에 뜨면 스킬을 쓸 수 없으니 정글러가 근처에 있을 때 각별히 주의하세요. 말파이트가 궁극기를 사용한 직후가 기회이므로, (R)\'불사의 분노\'를 켜고 끝까지 추격해 공격하세요. 라인을 밀어 넣은 뒤 (E)\'회전 베기\'로 빠르게 진입해 상대가 궁극기로 도망치지 못하게 압박하는 것이 중요해요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 신어 (Q)\'지진의 파편\'의 둔화 지속시간을 줄이는 것이 좋아요.', spell: '점멸과 순간이동을 추천해요. 말파이트의 강력한 군중 제어를 피하기 위해 점멸이 필수적이며, 순간이동으로 합류해 인원수 이점을 챙기는 것이 효율적이에요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 한 명에게만 맞으면 피해가 커지니 미니언 사이에 서서 혼자 맞지 않게 하세요. (P)\'암흑 탄생\' 효과가 켜지기 전에 스킬을 맞지 않도록 주의하며 (Q)\'피의 갈망\'으로 체력을 관리해야 해요. (E)\'회전 베기\'로 미니언을 정리하며 무리하게 붙지 않는 것이 좋아요.', lv3: '모데카이저의 (E)\'죽음의 손아귀\'나 (W)\'불멸\'이 빠진 것을 확인한 뒤에 딜교환을 시작하세요. (E)\'죽음의 손아귀\'를 피하기 위해 (E)\'회전 베기\'로 거리를 조절하거나 (W)\'조롱의 외침\'으로 상대의 공격력을 낮추며 전투하세요. (E)\'회전 베기\'로 분노를 빠르게 수급하여 지속적인 전투를 준비하는 것이 좋아요.', lv6: '모데카이저가 (R)\'죽음의 세계\'를 쓰면 능력치를 뺏기니 (R)\'불사의 분노\'로 버티며 역전을 노려야 해요. (R)\'죽음의 세계\' 안에서는 순간이동으로도 빠져나갈 수 없으니 조심하세요. 라인을 밀어두어 (R)\'죽음의 세계\'가 끝난 뒤 정글러와 함께 교전할 준비를 하세요.', item: '몰락한 왕의 검을 첫 코어로 올려서 전투 지속력을 높이세요. 신발은 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'불멸\'의 체력 회복 효과를 줄이고 마무리 피해도 넣기 좋아요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'을 던져 체력 비례 피해와 둔화를 걸어요. 이 투사체는 처음 맞는 대상에게만 적중하니 미니언 뒤에 숨어 막아내고, 틈을 노려 평타로 압박하세요. (Q)\'피의 갈망\'으로 체력을 관리하며 무리하게 들어가지 말고 짧은 딜교환을 반복하세요.', lv3: '(W)\'심장 전기 충격\'이 켜져 있을 때는 피해를 저장해 회복하므로, 무리하게 붙어 싸우지 말고 (W)\'조롱의 외침\'으로 공격력을 낮추며 거리만 유지하세요. (E)\'회전 베기\'를 사용해 빠르게 접근한 뒤 평타를 섞어 치고, (E)\'둔기에 의한 외상\'의 강화 공격이 들어오기 전에 빠르게 빠져나오세요. 문도가 통을 주워 체력을 회복하지 못하게 통 주변에서는 교전을 피하세요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 체력 회복량이 엄청나니, 궁극기가 빠진 시점을 노려 공격하세요. (R)\'불사의 분노\'를 켜고 들어가면 문도의 지속 피해를 무시하며 끝까지 추격해 킬각을 잡을 수 있어요. (P)\'가고 싶은 데로 간다\' 패시브는 처음 맞는 기절이나 속박 같은 이동 불가 효과에 저항하니, 정글러와 함께 노릴 때는 패시브가 빠졌는지 먼저 확인하세요.', item: '체력이 매우 높고 회복력이 좋은 문도를 상대하기 위해 몰락한 왕의 검을 첫 코어로 가세요. 신발은 (Q)\'오염된 뼈톱\'의 둔화 지속시간을 줄이고 마법 저항력을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사는 (R)\'최대 투여량\'과 패시브의 체력 재생이 매우 강력하므로 점화의 치유 감소 효과가 필수적이에요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 충전해 멀리서 견제하니, 화살이 날아오기 전에 옆으로 움직여 피하세요. (E)\'회전 베기\'로 빠르게 접근해 평타를 입히고 다시 빠지는 식으로 짧게 딜교환을 하세요. 첫 웨이브부터 계속 맞으면 체력이 많이 깎이니 거리 조절에 신경 쓰세요.', lv3: '(E)\'퍼붓는 화살\'의 오염된 지면에서는 (Q)\'피의 갈망\' 회복량이 줄어드니 장판 위에서 싸우지 마세요. 바루스가 도망갈 때 (W)\'조롱의 외침\'을 써서 공격력을 낮추고 이동 속도를 늦추세요. 평타로 (W)\'역병 화살\' 중첩이 쌓인 상태에서 (Q)\'꿰뚫는 화살\'을 맞으면 역병이 폭발해 피해가 커지니, 중첩이 쌓였을 때는 화살 궤적을 피하며 (E)\'회전 베기\'로 진입하세요.', lv6: '(R)\'부패의 사슬\'에 속박되면 진입이 막히니 바루스가 궁극기를 헛쓰게 유도하거나 스펠로 피하세요. (R)\'불사의 분노\'를 켜고 빠르게 붙어 공격하면 체력이 낮은 바루스를 쉽게 잡을 수 있어요. 라인을 밀어 넣고 정글러와 함께 갱킹을 노려 바루스의 도주 경로를 차단하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도를 높이고 바루스에게 붙어 피해를 주세요. 신발은 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 바루스의 견제 거리를 빠르게 좁혀야 공격을 성공시킬 수 있어요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'로 세 번째 공격마다 큰 피해를 입히므로 1~2레벨에는 긴 교환을 피하세요. (Q)\'피의 갈망\'을 활용해 체력을 관리하며 미니언을 챙기는 데 집중하고 베인의 평타 횟수를 확인하며 거리를 조절하세요.', lv3: '베인이 (E)\'선고\'를 사용해 지형에 부딪히면 기절하니 벽 근처에서는 싸우지 마세요. 베인이 등을 돌려 도망가려 할 때 (W)\'조롱의 외침\'을 사용해 이동 속도를 늦추고 (E)\'회전 베기\'로 빠르게 거리를 좁히며 몰아치세요.', lv6: '베인이 (R)\'결전의 시간\'을 사용하면 (Q)\'구르기\'가 투명해져서 추적이 어려워지니 조심하세요. (R)\'불사의 분노\'를 사용하여 베인의 강력한 피해를 버티면서 (E)\'회전 베기\'로 계속해서 압박하고 베인이 도망갈 때 정글러의 도움을 요청하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 전투력을 높이세요. 신발은 베인의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 베인의 거리를 빠르게 좁혀서 접근하세요.' },
    '볼리베어': { lv1: '볼리베어가 (Q)\'번개 강타\'를 사용해 달려오며 기절을 걸면 거리를 두어 피해를 최소화하세요. 1~2레벨에는 볼리베어의 기본 공격이 강력하니 (E)\'회전 베기\'를 활용해 미니언을 먹으며 파밍에 집중하세요.', lv3: '볼리베어의 (W)\'광란의 상처\' 표식이 남았을 때 다시 사용해 체력을 회복하지 못하도록 빠르게 거리를 벌리세요. (E)\'천공 분열\'의 폭발 범위 안에서 싸우면 볼리베어가 보호막을 얻으니 범위 밖에서 (E)\'회전 베기\'를 사용해 딜교환을 하세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 도약해 포탑을 비활성화하며 다이브를 시도할 수 있으니 낮은 체력일 때 주의하세요. 위기의 순간에 (R)\'불사의 분노\'를 켜서 버티고 (Q)\'피의 갈망\'을 사용해 체력을 회복하며 역공을 준비하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수로 교환을 지속하세요. 신발은 볼리베어의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 볼리베어의 (W)\'광란의 상처\'를 통한 체력 회복을 억제하세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 흡수하며 견제하는데 이는 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (Q)\'수혈\'이 강화되는 타이밍에는 무리하게 붙지 말고 (Q)\'피의 갈망\'으로 체력을 회복하며 버티는 것이 중요해요. 초반에는 섣부르게 공격하기보다 (Q)\'피의 갈망\'의 유지력을 활용해 체력을 관리하세요.', lv3: '(E)\'회전 베기\'로 빠르게 접근하되, 블라디미르가 (W)\'피의 웅덩이\'를 사용하면 대상으로 지정할 수 없으니 공격을 멈추고 끝날 때까지 기다려야 해요. (E)\'선혈의 파도\'는 적 유닛이 가로막을 수 있으니 미니언 뒤에 서서 피해를 줄이세요. (W)\'조롱의 외침\'을 사용해 상대의 공격력을 낮추고 도망갈 때 둔화를 걸어 압박하세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 즉시 (Q)\'피의 갈망\'으로 버티거나 거리 조절을 통해 빠르게 빠지세요. 블라디미르가 (W)\'피의 웅덩이\'를 소모한 시점이 가장 좋은 기회이니, (R)\'불사의 분노\'를 켜고 끝까지 추격해 처치하세요. 라인을 밀어 넣은 뒤 정글러와 함께 (W)\'피의 웅덩이\'가 빠진 상대를 노리는 것이 좋아요.', item: '마법사의 최후와 헤르메스의 발걸음을 추천해요. 마법 저항력을 높여 (Q)\'수혈\' 피해를 줄이고, 강인함으로 (E)\'선혈의 파도\' 둔화 지속시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. (Q)\'수혈\'과 (R)\'혈사병\'으로 회복하는 양이 매우 많으므로 점화로 치유량을 줄여야 처치할 수 있어요.' },
    '뽀삐': { lv1: '뽀삐가 (Q)\'망치 강타\'로 만든 둔화 지대를 조심하며 거리 조절을 하세요. 뽀삐가 방패를 주워 (P)\'강철의 외교관\' 보호막을 얻기 전에 (Q)\'피의 갈망\'을 활용해 짧게 딜교환하세요. 1~2레벨 구간에서는 무리하게 싸우기보다 미니언을 챙기며 안정적으로 보내세요.', lv3: '뽀삐의 (E)\'용감한 돌진\'에 밀려 벽에 부딪히면 기절하니 벽을 등지고 서지 마세요. (W)\'굳건한 태세\'가 켜진 동안 (E)\'회전 베기\'로 돌진하면 막혀서 둔화되고 이동 스킬을 쓸 수 없으니, 효과가 끝난 뒤에 진입해 (W)\'조롱의 외침\'으로 공격력을 낮추며 딜교환을 시작하세요. 뽀삐의 스킬을 확인하며 딜교환 타이밍을 잡는 것이 중요해요.', lv6: '(R)\'불사의 분노\'를 사용해 죽지 않는 동안 뽀삐를 강하게 압박하세요. 뽀삐가 (R)\'수호자의 심판\'으로 멀리 날려버릴 수 있으니 궁극기 사용 시 위치 선정이 중요해요. 뽀삐의 (E)\'용감한 돌진\'이 빠진 시점에 (E)\'회전 베기\'로 피해를 입히며 킬을 노리세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 뽀삐의 기본 공격 피해를 줄여주고 몰락한 왕의 검은 생명력 흡수와 공격 속도를 줘요.', spell: '점멸과 점화를 추천해요. 점화로 뽀삐에게 추가 피해를 입히며 킬을 노리세요.' },
    '사이온': { lv1: '사이온은 (E)\'학살자의 포효\'로 미니언을 밀어내며 방어력을 깎으니 미니언과 일직선으로 서지 마세요. (Q)\'대량 학살 강타\'를 충전하는 동작이 보이면 옆으로 비켜나서 헛치게 만든 뒤 (E)\'회전 베기\'로 접근해 평타를 넣으세요.', lv3: '(W)\'영혼의 용광로\' 보호막이 켜진 동안에는 피해가 흡수되니 보호막이 터질 때까지 기다렸다가 (E)\'회전 베기\'로 진입하세요. (E)\'학살자의 포효\'로 둔화되었을 때 (W)\'조롱의 외침\'을 써서 상대의 공격력을 낮추고 (Q)\'피의 갈망\'으로 체력을 회복하며 끈질기게 괴롭히세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 직선으로 돌진하며 부딪힌 적을 띄우니 돌진 경로에서 옆으로 비켜나세요. (R)\'불사의 분노\'를 켜고 진입하면 사이온의 폭발적인 피해를 버티며 일방적인 공격이 가능해요. 상대가 죽은 뒤 (P)\'영광스러운 죽음\'으로 반격할 수 있으니 완전히 사라질 때까지 거리를 유지하세요.', item: '몰락한 왕의 검을 가서 체력이 높은 사이온에게 효율적인 피해를 입히세요. 신발은 (E)\'학살자의 포효\' 둔화와 (R)\'멈출 수 없는 맹공\' 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인을 빠르게 밀어내므로 순간이동을 통해 복귀하며 손해를 최소화하세요.' },
    '사일러스': { lv1: '사일러스는 (Q)\'사슬 후려치기\'로 둔화를 걸며 견제하고 (P)\'페트리사이트 폭발\'이 충전되면 평타로 추가 마법 피해를 입혀요. 사슬이 교차하며 터지는 지점을 피하면서 (E)\'회전 베기\'로 분노를 쌓고 미니언을 챙기세요. 초반에는 사일러스의 견제를 받아내며 무리하게 붙기보다 거리를 조절하세요.', lv3: '사일러스가 (E)\'도주 / 억압\'의 사슬을 던질 때 옆으로 움직여 공중으로 띄워지는 것을 피하세요. 사일러스가 (W)\'국왕시해자\'로 돌진해 들어오는 순간 (W)\'조롱의 외침\'으로 평타 공격력을 낮추세요. 사일러스의 주요 스킬이 빠진 타이밍에 (E)\'회전 베기\'로 접근해 딜교환을 시도하세요.', lv6: '사일러스가 (R)\'강탈\'로 (R)\'불사의 분노\'를 훔쳐 가면 사일러스도 죽지 않게 되니 체력이 낮은 상태에서 무리하게 싸우지 마세요. 사일러스가 스킬을 사용해 들어올 때 (R)\'불사의 분노\'를 켜고 맞대응하며 끝까지 추격해 보세요. 사일러스가 훔친 궁극기로 인해 변수가 생길 수 있으니 정글러의 위치를 확인하며 라인을 관리하세요.', item: '첫 코어로 몰락한 왕의 검을 선택해 생명력 흡수와 공격 속도를 확보하세요. 신발은 사일러스의 마법 피해를 줄이고 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 사일러스의 (W)\'국왕시해자\' 체력 회복 효과를 감소시켜 킬각을 잡으세요.' },
    '세주아니': { lv1: '1~2레벨에는 상대의 (Q)\'혹한의 맹습\'에 맞지 않도록 거리를 잘 조절하며 미니언을 챙겨요. (W)\'혹한의 서릿발\'에 둔화되면 걸어서 빠지기 어려우니 무리하게 붙어 있지 말고, 빠져야 할 때는 (E)\'회전 베기\'로 거리를 벌려요. 상대의 서리 갑옷이 활성화되어 방어력이 높아지는 구간은 조심하며 플레이해요.', lv3: '스킬이 모인 뒤에는 상대의 (E)\'만년 서리\' 중첩이 쌓이지 않도록 주의하며 딜교환을 해요. (Q)\'혹한의 맹습\'을 조심하며 (W)\'조롱의 외침\'으로 상대의 공격력을 낮추는 방식으로 대응해요. (E)\'회전 베기\'를 사용해 적절한 위치를 잡으며 (Q)\'피의 갈망\'으로 체력을 관리해요.', lv6: '(R)\'빙하 감옥\'에 걸려 기절하면 스킬을 쓸 수 없으니 (R)\'불사의 분노\'는 올가미가 날아오기 전에 미리 켜 두세요. 상대의 주요 스킬이 빠진 타이밍에 (E)\'회전 베기\'로 진입하여 킬각을 보세요. 라인을 빠르게 밀어 넣으며 상대 정글의 개입에 대비해요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 헤르메스의 발걸음으로 마법 저항력과 강인함을 얻어 군중 제어 지속 시간을 줄여요. 몰락한 왕의 검으로 강력한 피해를 입혀 전투를 주도해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 증가와 유닛 충돌 무시로 상대를 끝까지 추격하기 쉬워요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 켜고 달려와 강력한 평타 피해를 입히니 정면에서 오래 싸우지 마세요. (E)\'회전 베기\'로 분노를 빠르게 쌓으며 짧게 치고 빠지는 방식으로 체력을 관리하세요. (P)\'투기장의 투지\'로 인해 세트가 체력을 회복하며 버티는 상황을 만들지 않는 것이 중요해요.', lv3: '세트 양옆에 미니언과 함께 있을 때 (E)\'안면 강타\'를 맞으면 기절하니 위치 선정에 주의하세요. (W)\'강펀치\'의 중심선에 맞으면 고정 피해가 들어오니 최대한 옆으로 피하거나 거리 조절을 하세요. (W)\'조롱의 외침\'으로 세트의 공격력을 낮춘 뒤 (E)\'회전 베기\'로 진입해 짧게 딜교환을 하세요.', lv6: '(R)\'대미 장식\'에 제압당하면 스킬을 쓸 수 없으니 (R)\'불사의 분노\'는 붙잡히기 전에 미리 켜 두세요. (R)\'대미 장식\' 이후에는 세트의 큰 군중 제어기가 빠진 상태이므로 이때를 놓치지 말고 공격하세요. 세트가 (E)\'안면 강타\'로 정글러와 연계하기 좋으니 라인을 너무 깊게 밀지 말고 조심하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 세트의 높은 체력을 깎고 생명력 흡수로 버티세요. 신발은 평타 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'투기장의 투지\'를 통한 세트의 체력 회복을 점화의 치유 감소 효과로 억제하세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 입히며 (P)\'기 보호막\'을 얻으니 무리하게 맞교환하지 마세요. 1~2레벨에는 쉔이 (Q)\'황혼 강습\'의 기의 검을 활용하기 전에 평타로 견제하며 분노를 쌓으세요. (E)\'회전 베기\'를 활용해 미니언 사이에서 분노를 수급하며 거리를 조절하는 것이 중요해요.', lv3: '쉔이 (W)\'의지의 결계\'를 펼치면 결계 안 아군에 대한 평타가 차단되니 결계가 사라질 때까지 (Q)\'피의 갈망\'으로 체력을 회복하며 기다리세요. 쉔이 (E)\'그림자 돌진\'으로 도발을 시도하면 무리하게 맞서지 말고 도발이 빠진 뒤에 (E)\'회전 베기\'로 거리를 좁히세요. 쉔의 (Q)\'황혼 강습\' 둔화에 걸리지 않도록 주의하며 공격 템포를 조절해요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용하여 다른 라인에 합류하면 빠르게 라인을 밀어 압박해야 해요. 도발 중에는 스킬을 쓸 수 없으니 (E)\'그림자 돌진\'을 맞기 전에 (R)\'불사의 분노\'를 미리 켜고 끝까지 공격하면 킬을 노릴 수 있어요. 쉔이 (P)\'기 보호막\'을 소모한 뒤에 (Q)\'피의 갈망\'과 함께 집중적으로 몰아붙이세요.', item: '첫 코어로 몰락한 왕의 검을 가세요. 신발은 쉔의 마법 피해를 줄여주는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 쉔이 (P)\'기 보호막\'을 두르기 전의 짧은 틈에 점화를 섞어 킬각을 만드세요.' },
    '쉬바나': { lv1: '1~2레벨에는 (E)\'회전 베기\'를 활용해 미니언과 함께 접근하며 분노를 쌓는 것이 중요해요. 상대가 (Q)\'잉걸불 일격\'으로 압박할 때는 무리하게 맞붙기보다 거리를 조절하며 받아내세요. 첫 웨이브를 안정적으로 가져가며 성장에 집중해요.', lv3: '스킬이 모이면 (W)\'조롱의 외침\'을 사용해 상대의 공격력을 낮추며 딜교환을 시작하세요. 상대가 (W)\'지옥불 방패\'의 보호막을 켜고 폭발 피해를 입히기 전 타이밍을 노려야 해요. (Q)\'피의 갈망\'으로 체력을 회복하며 끈질기게 싸워야 해요.', lv6: '상대가 (R)\'용의 강림\'으로 경로의 적을 달아나게 만들기 전에 (R)\'불사의 분노\'를 미리 켜고 추격하세요. 용 형상의 쉬바나가 강화된 (Q)\'잉걸불 일격\'을 쓸 때 매우 강력하니 조심해야 해요. 라인을 밀어 넣고 정글러의 개입을 경계하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공하고 몰락한 왕의 검은 생명력 흡수로 전투를 지속하게 도와줘요.', spell: '점멸과 점화를 추천해요. 점멸은 위치 선정을 도와주며 점화는 상대가 (W)\'지옥불 방패\'를 통해 체력을 회복하는 것을 억제하며 킬을 노리기 좋기 때문이에요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제를 넣고 (P)\'굶주린 새떼\'로 체력을 회복해요. 번개가 여러 갈래로 퍼지니 옆으로 움직여 피해를 줄이고 (E)\'회전 베기\'로 진입해 평타 딜교환을 하세요. 초반에는 체력 관리를 하며 (Q)\'피의 갈망\'으로 버티는 것이 중요해요.', lv3: '(E)\'속박명령\'은 돌아올 때 속박하고 끌어당기니 파동이 나가는 방향을 보고 옆으로 피하세요. (W)\'제국의 눈\'의 둔화에 걸리면 (E)\'회전 베기\'로 빠르게 접근해 공격하고 (W)\'조롱의 외침\'을 써서 상대의 공격력을 낮추세요. 속박에 걸려도 평타는 칠 수 있으니 당황하지 말고 계속 공격하세요.', lv6: '스웨인이 (R)\'악의 승천\'으로 생명력을 흡수하며 버티니 (R)\'불사의 분노\'를 켜고 끝까지 추격해 처치하세요. 변신 중에는 주변 적을 둔화시키므로 (E)\'회전 베기\'를 적절히 섞어 거리 조절을 하며 빠르게 딜을 넣으세요. 라인을 밀어 넣고 타워 아래에서 스웨인이 (R)\'악의 승천\'을 켜게 유도하면 정글러와 함께 잡기 편해요.', item: '마법사의 최후를 첫 코어로 가서 마법 저항력을 얻고 공격 속도를 높이세요. 신발은 (E)\'속박명령\'의 속박과 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 스웨인은 (R)\'악의 승천\'과 (P)\'굶주린 새떼\'로 회복량이 매우 높으니 점화로 이를 억제해야 해요.' },
    '스카너': { lv1: '스카너의 (Q)\'부서진 대지/지반 돌출\' 투사체가 날아올 때 거리를 조절하며 피해를 최소화하세요. (E)\'회전 베기\'를 활용해 미니언을 정리하며 분노를 쌓는 데 집중해요. 초반에는 무리한 진입보다 체력 관리에 신경 써야 해요.', lv3: '스카너가 (W)\'대지의 수호자\'로 보호막을 생성했을 때는 무리하게 딜교환하지 마세요. (E)\'이쉬탈의 격돌\'에 맞고 벽에 부딪혀 기절하지 않도록 지형 근처에서는 주의해야 해요. 상대의 (Q)\'부서진 대지/지반 돌출\' 둔화가 끝난 뒤 (E)\'회전 베기\'로 거리를 좁혀 공격하세요.', lv6: '스카너가 (R)\'꿰뚫기\'로 제압하면 스킬을 쓸 수 없으니 (R)\'불사의 분노\'는 꼬리가 닿기 전에 미리 켜 두세요. 제압이 풀린 직후 (Q)\'피의 갈망\'으로 체력을 회복하며 반격하는 구도를 만드세요. 라인을 빠르게 밀어 넣고 정글러의 개입에 대비하며 조심스럽게 움직여요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 기본 공격 피해를 줄이면서 높은 체력을 가진 스카너를 효과적으로 공격할 수 있어요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 증가로 스카너에게 접근하거나 이탈하기 좋아요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'를 사용해 라인을 빠르게 밀며 계속 도망가려 해요. 무리하게 쫓아가다 독구름에 닿지 말고, 신지드가 미니언을 먹으러 올 때 평타로 견제하세요. (Q)\'피의 갈망\'으로 체력을 회복하며 짧은 딜교환을 반복하세요.', lv3: '(W)\'초강력 접착제\' 위에서는 둔화되고 이동 스킬을 쓸 수 없으니 접착제가 깔린 지역은 피하세요. (E)\'던져넘기기\'에 맞은 뒤 접착제 위로 떨어지면 속박되니 항상 신지드의 뒤쪽 위치를 확인하세요. (W)\'조롱의 외침\'으로 상대 공격력을 낮추고 짧게 진입한 뒤 빠지세요.', lv6: '(R)\'광기의 물약\'을 마신 신지드는 매우 단단해지고 독구름에 치유 감소가 붙으니 정면 승부를 피하세요. 신지드의 주요 스킬이 빠진 시점에 (E)\'회전 베기\'로 진입하고 (R)\'불사의 분노\'로 버티며 끝까지 추격하세요. 라인을 너무 밀면 (E)\'던져넘기기\' 한 번에 포탑으로 밀려날 수 있으니 주의하세요.', item: '몰락한 왕의 검을 추천해요. 공격 속도와 생명력 흡수를 챙기고 체력이 높은 신지드에게 효율적인 피해를 줄 수 있어요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 유체화를 추천해요. (P)\'독성 급류\'로 빠르게 도망가는 신지드를 끝까지 추격해 잡기 위해 유체화가 꼭 필요해요.' },
    '신짜오': { lv1: '(E)\'회전 베기\'로 분노를 빠르게 쌓으며 짧게 딜교환을 하세요. 신 짜오의 (Q)\'삼조격\' 세 번째 공격에 공중으로 띄워지지 않게 거리 조절을 하는 것이 중요해요. 체력이 낮아지면 (Q)\'피의 갈망\'으로 회복하며 버티세요.', lv3: '상대가 (E)\'무쌍돌격\'으로 진입할 때 (W)\'조롱의 외침\'을 써서 공격력을 낮추세요. (W)\'풍전참뢰\'의 둔화에 걸리지 않도록 주의하며 (E)\'회전 베기\'로 빠르게 진입과 이탈을 반복해요. 상대의 (Q)\'삼조격\' 세 번째 공격이 빠진 타이밍에 공격하세요.', lv6: '(R)\'불사의 분노\'를 켜고 상대의 (R)\'현월수호\' 피해를 견디며 끝까지 추격하세요. 상대가 (R)\'현월수호\'로 밀어내려 할 때 (E)\'회전 베기\'를 사용해 다시 거리를 좁히는 것이 좋아요. 정글 개입이 잦은 구간이니 (Q)\'피의 갈망\'으로 체력을 관리하세요.', item: '판금 장화와 몰락한 왕의 검을 가세요. 판금 장화로 기본 공격 피해를 줄이고 몰락한 왕의 검의 생명력 흡수로 유지력을 높이기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀와 합류를 챙기고 점멸로 상대의 핵심 기술을 피하거나 킬각을 잡으세요.' },
    '아이번': { lv1: '아이번의 (Q)\'덩굴뿌리\'는 처음 적중한 대상만 속박하므로 미니언 뒤에 숨어 피하세요. (E)\'회전 베기\'로 분노를 쌓으며 적절한 거리를 유지하고, 체력이 낮아지면 (Q)\'피의 갈망\'으로 회복하며 버티세요.', lv3: '아이번의 (Q)\'덩굴뿌리\'가 빠진 것을 확인한 뒤 (E)\'회전 베기\'로 빠르게 진입해 공격하세요. 상대가 도망갈 때 (W)\'조롱의 외침\'을 사용해 이동 속도를 늦추고 추격하며 (Q)\'피의 갈망\'으로 유지력을 챙겨요. (E)\'보호의 씨앗\' 보호막이 터지며 둔화가 걸릴 수 있으니 주의하세요.', lv6: '(R)\'불사의 분노\'를 켜고 (R)\'데이지!\'의 공격을 견디며 아이번 본체에게 빠르게 접근하세요. 데이지가 같은 챔피언을 세 번 연속 공격하면 충격파로 띄워 올리니 데이지 곁에 오래 머물지 말고 (E)\'회전 베기\'로 아이번에게 붙어야 해요. 라인을 밀어두고 상대 정글러의 개입을 조심하며 킬각을 보세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 구매하세요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공하며 몰락한 왕의 검은 생명력 흡수와 공격 속도를 높여줘요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해는 교환 뒤 체력이 낮아진 아이번을 마무리하기 좋아요.' },
    '아지르': { lv1: '(W)\'일어나라!\'의 견제가 심하니 무리하게 진입하지 말고 체력을 보존하세요. 첫 웨이브를 어느 정도 받아낸 뒤 (E)\'회전 베기\'로 빠르게 거리를 좁혀 공격하세요. 체력이 너무 낮아지면 (Q)\'피의 갈망\'으로 회복하며 버텨야 해요.', lv3: '(Q)\'사막의 맹습\'에 맞으면 둔화되어 추격이 어려우니 옆으로 피하며 진입하세요. 근접했을 때 (W)\'조롱의 외침\'을 사용해 상대 공격력을 낮추고 계속 압박하세요. 상대가 (E)\'신기루\'로 거리를 벌리기 전에 (E)\'회전 베기\'로 다시 붙어야 해요.', lv6: '(R)\'불사의 분노\'를 켜고 진입하되 (R)\'황제의 진영\'에 밀려나지 않도록 주의하세요. 상대의 밀쳐내기 스킬이 빠진 타이밍에 킬각을 잡으세요. 라인을 밀어넣고 정글러를 호출해 (R)\'황제의 진영\' 변수를 함께 제거하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높여 (W)\'일어나라!\'의 피해를 줄이고 생명선 보호막으로 생존력을 높여야 해요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (E)\'신기루\'나 (Q)\'사막의 맹습\' 이후 거리를 좁히고 순간이동으로 라인에 복귀해요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 둔화를 걸며 견제하므로 아칼리의 (P)\'암살자의 표식\' 원 경계를 주의하며 거리를 조절하세요. 아칼리가 (P)\'암살자의 표식\'을 활용해 강화 평타를 날리려 할 때 (Q)\'피의 갈망\'으로 체력을 관리하며 파밍에 집중하세요.', lv3: '아칼리가 (E)\'표창곡예\'로 표식을 남기고 돌진해오면 (W)\'조롱의 외침\'을 사용하여 공격력을 낮추고 도망가는 아칼리를 둔화시키세요. (W)\'황혼의 장막\' 안의 아칼리는 지정할 수 없지만, 아칼리가 공격하거나 스킬을 써서 모습이 드러나는 순간 (E)\'회전 베기\'를 맞히며 딜교환을 시도하세요.', lv6: '아칼리가 (R)\'무결처형\'으로 두 번 돌진하며 들어오면 (R)\'불사의 분노\'를 사용해 생존하며 맞대응하세요. 연막 안의 아칼리는 대상으로 지정할 수 없어 평타를 칠 수 없으니 연막이 사라지거나 모습이 드러날 때까지 기다리세요. 아칼리가 진입할 때 정글러를 불러 함께 압박하면 좋아요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 아칼리의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 아칼리의 체력이 낮아졌을 때 확실한 마무리 피해를 입히세요.' },
    '아크샨': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\' 견제를 최대한 피하며 경험치 위주로 행동하세요. (E)\'회전 베기\'로 무리하게 접근하기보다 부메랑 궤적에서 벗어나 체력을 관리하며 기회를 엿보세요. 체력이 낮아지면 (Q)\'피의 갈망\'을 사용하여 체력을 회복하며 버티세요.', lv3: '3레벨부터는 (E)\'회전 베기\'로 진입한 뒤 (W)\'조롱의 외침\'을 사용하여 상대의 공격력을 낮추세요. 상대가 (E)\'영웅의 비상\'으로 거리를 벌리려 하면 끝까지 추격하며 공격을 퍼부으세요. (Q)\'복수의 부메랑\'이 돌아오는 궤적을 피해 무빙하며 딜교환을 이어가세요.', lv6: '6레벨 이후에는 (R)\'불사의 분노\'를 켜고 과감하게 들어가서 킬각을 잡으세요. 다만 (R)\'인과응보\'는 잃은 체력에 비례해 큰 피해를 입히므로 체력이 너무 낮을 때 정면에서 맞지 않게 주의하세요. (E)\'회전 베기\'를 활용해 라인을 빠르게 밀고 정글 개입에 대비하세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화로 기본 공격 피해를 줄이고 몰락한 왕의 검의 공격 속도와 생명력 흡수로 교환을 이어가세요.', spell: '점멸과 유체화를 추천해요. (E)\'영웅의 비상\'으로 빠르게 도망치는 상대를 끝까지 추격해서 잡아내기 위해서예요.' },
    '아트록스': { lv1: '아트록스가 (Q)\'다르킨의 검\'을 휘두를 때 끝자락에 맞으면 공중으로 뜨니 거리 조절에 집중하세요. (Q)\'피의 갈망\'으로 체력을 관리하며 아트록스의 스킬을 피하며 파밍하세요. 초반에는 아트록스의 공격력이 강하니 무리한 교환보다는 미니언을 챙기는 데 집중해요.', lv3: '아트록스가 (W)\'지옥사슬\'을 사용하면 중앙으로 끌려가지 않도록 빠르게 범위 밖으로 벗어나세요. (E)\'회전 베기\'를 사용하여 아트록스의 (Q)\'다르킨의 검\' 범위를 피하거나 거리를 좁히며 딜교환을 시도해요. 아트록스가 (E)\'파멸의 돌진\'으로 들어오면 (W)\'조롱의 외침\'을 사용하여 공격력을 낮추며 대응하세요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 사용하여 공격력과 회복량이 늘어나면 정면 승부는 피하는 것이 좋아요. 아트록스의 폭발적인 피해가 들어올 때 (R)\'불사의 분노\'를 사용하여 버티며 치명타를 몰아치세요. 라인을 빠르게 밀어 넣고 정글러를 불러서 아트록스의 스킬 지속 시간이 끝나기 전에 압박하세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주며 몰락한 왕의 검은 전투 중에 생명력을 흡수하여 버티게 도와줘요.', spell: '점멸과 점화를 추천해요. 점화는 아트록스의 (P)\'사신 태세\'나 (E)\'파멸의 돌진\'으로 얻는 체력 회복 효과를 감소시키는 데 유용해요.' },
    '암베사': { lv1: '암베사는 (P)\'용사냥개의 발걸음\'을 통해 스킬 사용 후 빠르게 접근하여 평타를 강화하므로 거리를 잘 유지해야 해요. 암베사가 (Q)\'교활한 휩쓸기\'를 사용하며 들어올 때 (E)\'회전 베기\'로 분노를 쌓으며 대응하세요. 초반에는 암베사의 돌진에 휘둘리지 말고 미니언을 통해 분노를 모으는 데 집중하세요.', lv3: '암베사가 (W)\'배척\'을 준비하는 동안 챔피언에게 맞으면 내려치는 피해가 커지니, 보호막이 켜진 동안은 공격을 멈추고 기다리세요. (E)\'찢어 가르기\'의 둔화에 걸리지 않도록 주의하며 암베사의 스킬 연계가 끝나면 (W)\'조롱의 외침\'을 사용하여 공격력을 낮추세요. (Q)\'피의 갈망\'을 사용하여 체력을 관리하며 암베사의 스킬이 빠진 타이밍에 딜교환을 시도하세요.', lv6: '암베사의 (R)\'공개 처형\'은 일직선상에서 가장 멀리 있는 챔피언에게 순간이동해 제압한 뒤 기절시키니, 그동안에는 (R)\'불사의 분노\'를 쓸 수 없어요. 체력이 낮은 상태라면 궁극기가 들어오기 전에 (R)\'불사의 분노\'를 미리 켜 두거나 포탑 쪽으로 물러나세요. 궁극기 사거리가 길어 갑자기 진입할 수 있으니 포탑 근처에서 라인을 관리하며 정글러를 부르세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 암베사와의 근접 교전에서 생명력 흡수와 공격 속도를 챙기세요. 신발은 암베사의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 암베사는 (R)\'공개 처형\'의 기본 지속 효과로 스킬 피해만큼 체력을 회복하니 점화로 회복을 줄이며 킬각을 잡으세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 둔화와 기절을 걸며 멀리서 견제해요. 구체가 날아오는 궤적을 보고 옆으로 비켜 걸으며 다가가고 (Q)\'피의 갈망\'으로 체력을 관리하세요.', lv3: '애니비아가 (W)\'결정화\'로 앞을 막으면 접근이 힘드니 벽이 사라진 뒤에 움직이세요. (Q)\'냉기 폭발\'을 피했다면 (E)\'회전 베기\'로 붙어서 (W)\'조롱의 외침\'을 사용해 공격력을 낮추세요. (E)\'동상\'은 냉각 상태인 대상에게 피해가 커지니 구체를 맞은 직후엔 딜교환을 피해요.', lv6: '(R)\'얼음 폭풍\' 안에서는 둔화 때문에 접근이 어려우니 장판이 끝난 뒤 (R)\'불사의 분노\'를 켜고 진입하세요. 애니비아는 (P)\'환생\'으로 체력을 회복하니 쓰러뜨린 뒤에는 알을 빠르게 공격해야 해요. 라인을 밀어 넣고 (W)\'결정화\'가 빠진 타이밍에 정글러와 함께 압박하세요.', item: '헤르메스의 발걸음을 가서 마법 저항력과 강인함으로 군중 제어 지속시간을 줄이세요. 첫 코어로 몰락한 왕의 검을 가서 전투 지속력을 높여요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해로 (Q)\'냉기 폭발\' 교환 뒤 마무리하기 좋아요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\' 중첩을 쌓아 회오리바람을 날리려 할 때 거리를 조절하세요. (P)\'낭인의 길\' 보호막이 있을 때는 무리하게 딜교환을 하기보다 평타로 보호막을 먼저 제거하는 것이 좋아요. (Q)\'피의 갈망\'을 사용하여 체력을 관리하며 야스오의 초반 견제를 버텨내세요.', lv3: '야스오가 (E)\'질풍검\'으로 미니언을 타고 들어올 때 (W)\'조롱의 외침\'을 사용하여 공격력을 낮추고 이동 속도를 늦추세요. 야스오의 (W)\'바람 장막\'은 투사체를 막는 스킬이라 트린다미어의 근접 공격에는 영향을 주지 않으니 과감하게 붙으세요. (E)\'회전 베기\'를 아껴 두었다가 야스오가 (E)\'질풍검\'으로 빠질 때 따라붙으며 싸우세요.', lv6: '야스오가 (Q)\'강철 폭풍\'의 회오리로 적을 띄운 뒤 (R)\'최후의 숨결\'로 들어오는 연계를 가장 조심해야 해요. 공중에 뜬 동안에는 스킬을 쓸 수 없으니 (R)\'불사의 분노\'는 회오리를 맞기 전에 미리 켜 두고 역공을 펼치세요. 라인을 너무 밀어두면 야스오가 (E)\'질풍검\'으로 빠지거나 정글러의 개입이 쉬워지니 주의하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 현재 체력 비례 추가 피해로 야스오를 압박하세요. 신발은 야스오의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'낭인의 길\' 보호막 이후에 마무리 피해를 입혀 킬각을 잡으세요.' },
    '오공': { lv1: '1~2레벨에는 오공이 (Q)\'파쇄격\'으로 늘어난 사거리와 방어력 감소 효과를 활용하기 전에 거리를 유지하세요. (E)\'회전 베기\'로 미니언을 적중시켜 분노를 미리 쌓아두는 것이 좋아요. 오공의 공격 사거리가 길어지는 구간에서는 무리하게 맞붙지 말고 체력을 보존하세요.', lv3: '오공이 (W)\'분신 전사\'를 쓰면 움직이지 않는 분신이 남으니 분신에 스킬을 쓰지 않도록 주의하세요. 오공이 (E)\'근두운 급습\'으로 돌진할 때 (W)\'조롱의 외침\'을 사용하여 오공의 공격력을 낮추며 대응해요. 오공의 돌진기가 빠진 타이밍에 (Q)\'피의 갈망\'을 사용해 체력을 회복하며 딜교환을 하세요.', lv6: '오공의 (R)\'회전격\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니 궁극기를 사용하는 타이밍을 잘 살펴야 해요. 체력이 낮다면 (R)\'불사의 분노\'는 (R)\'회전격\'에 맞기 전에 미리 켜 두거나 첫 번째 회전이 끝난 틈에 켜고 반격하세요. 오공이 궁극기를 쓴 뒤에는 (E)\'회전 베기\'를 활용해 빠르게 분노를 수급하며 압박을 이어가세요.', item: '몰락한 왕의 검을 코어 아이템으로 선택해 공격 속도와 생명력 흡수로 지속적인 교환을 준비하세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 오공의 체력을 깎으며 킬각을 잡으세요.' },
    '오로라': { lv1: '오로라가 (Q)\'이중 저주\'를 사용하면 저주가 되돌아오는 경로를 조심하며 옆으로 움직여 피해를 피하세요. (Q)\'피의 갈망\'으로 체력을 유지하며 오로라의 견제를 견뎌내고 미니언을 놓치지 마세요.', lv3: '오로라가 (E)\'마법의 문\'을 써서 뒤로 도약하면 무리하게 쫓지 말고 (W)\'조롱의 외침\'으로 공격력을 낮추며 거리를 조절하세요. (W)\'장막 너머로\'로 투명해진 상태에서는 (E)\'회전 베기\'를 적중시키기 어려우니 오로라가 모습을 드러낼 때까지 기다리세요.', lv6: '오로라의 (R)\'세계의 경계\' 영역 안은 둔화와 이동이 잦아 위치를 잡기 어려우니 주의하세요. (R)\'불사의 분노\'를 사용해 오로라의 공격을 버티며 (E)\'회전 베기\'를 맞히고 강력하게 몰아붙이세요.', item: '헤르메스의 발걸음을 신어서 마법 저항력과 강인함을 확보하세요. 첫 코어 아이템은 몰락한 왕의 검을 선택해 오로라를 끝까지 추격하세요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 (E)\'마법의 문\'이나 (R)\'세계의 경계\'를 이용해 이동하는 오로라를 빠르게 따라잡으세요.' },
    '오른': { lv1: '(Q)\'용암 균열\'이 지나간 자리에 생기는 용암 기둥을 조심하며 옆으로 비켜서세요. (P)\'간이 대장간\' 덕분에 오른의 방어력이 높으니 무리한 딜교보다는 (E)\'회전 베기\'로 미니언과 함께 견제하며 분노를 쌓으세요. 초반에는 체력을 보존하며 파밍에 집중하는 것이 좋아요.', lv3: '오른이 (W)\'불꽃 풀무질\'을 사용하면 불안정 상태가 되어 이후 군중 제어 지속시간이 늘어나니 조심하세요. (E)\'화염 돌진\'을 사용할 때 벽 근처에 있으면 공중으로 띄워질 수 있으니 지형지물을 등지고 서지 마세요. (Q)\'피의 갈망\'으로 체력을 회복하며 오른의 스킬이 빠진 타이밍에 (E)\'회전 베기\'로 붙어 딜교하세요.', lv6: '(R)\'대장장이 신의 부름\' 정령이 다가올 때 진행 방향을 잘 확인하고 정령에 부딪혀 띄워지지 않게 주의하세요. (R)\'불사의 분노\'를 사용하여 오른의 강력한 연계 공격을 버텨내며 (E)\'회전 베기\'로 끝까지 추격하세요. 오른이 궁극기를 사용한 뒤에는 라인을 빠르게 밀어 정글의 개입을 방지하며 성장하세요.', item: '첫 코어로 몰락한 왕의 검을 가서 안개의 검 효과를 활용하세요. 신발은 공격 속도를 높여주는 광전사의 군화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 이동 속도를 높여 오른의 (Q)\'용암 균열\'을 피하거나 (E)\'회전 베기\'로 빠르게 접근하기 쉬워요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 맞히면 방어력 감소와 둔화를 겪으니 도끼가 날아오는 방향을 잘 보고 피하세요. 1~2레벨에는 올라프의 정면 교환이 강하므로 (E)\'회전 베기\'로 미니언을 챙기며 거리를 유지하는 게 좋아요. 올라프가 도끼를 주우러 움직일 때 (Q)\'피의 갈망\'으로 체력을 관리하며 버티세요.', lv3: '올라프가 (W)\'버티기\'를 사용하면 공격 속도와 보호막이 생기니 그 타이밍에는 (E)\'회전 베기\'로 무리하게 싸우지 마세요. 올라프의 (Q)\'역류\'가 빠진 것을 확인한 뒤에 (Q)\'피의 갈망\'으로 체력을 회복하며 딜교환을 시도하세요. 치명타가 터지면 (E)\'회전 베기\'의 재사용 대기시간이 줄어드니 적극적으로 활용해 보세요.', lv6: '올라프가 (R)\'라그나로크\'를 켜면 이동 방해 효과에 면역이 되니 정면에서 맞붙는 것을 피하고 지속 시간이 끝나길 기다리세요. 올라프의 체력이 낮아 (P)\'광전사의 분노\' 효과로 흡혈이 강해지면 (R)\'불사의 분노\'를 사용해 버텨야 해요. 라인이 깊게 밀려 있으면 올라프의 (E)\'무모한 강타\'로 인한 처치에 주의하며 정글러의 도움을 요청하세요.', item: '판금 장화와 몰락한 왕의 검을 선택하세요. 올라프의 기본 공격 피해를 줄이고 생명력 흡수로 맞딜을 준비해요.', spell: '점멸과 점화를 추천해요. 점화로 올라프의 체력 회복을 억제하세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'을 중첩시켜 적을 띄워 올려요. 중첩이 쌓였을 때 무리하게 들어가지 말고 (Q)\'피의 갈망\'으로 체력을 회복하며 버티세요. 두 번째 평타마다 (P)\'사냥꾼의 길\' 마법 피해가 들어오니 짧게 치고 빠지세요.', lv3: '(E)\'영혼해방\'을 사용한 요네는 육신으로 돌아오는 시점에 피해를 다시 입히니 그 타이밍에 거리를 벌리세요. (W)\'영혼 가르기\'로 보호막을 얻기 전에 (E)\'회전 베기\'로 진입해 빠르게 공격하세요. 요네가 도망가면 (W)\'조롱의 외침\'을 써서 이동 속도를 늦추고 추격하세요.', lv6: '요네가 (R)\'운명봉인\'으로 끌어당기면 공중에 떠서 스킬을 쓸 수 없으니 (R)\'불사의 분노\'는 맞기 전에 미리 켜 두세요. 요네의 (E)\'영혼해방\'이 끝나는 지점을 예측해 미리 대기하다가 공격하면 킬각을 잡기 편해요. (E)\'회전 베기\'로 빠르게 접근해 요네의 진입 경로를 차단하며 정글러의 개입에 대비하세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 판금 장화가 좋은데 요네의 기본 공격 피해를 줄여주기 때문이에요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 상승과 유닛 충돌 무시 효과로 요네의 (Q)\'필멸의 검\' 돌풍 범위에서 빠르게 벗어나기 좋아요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 미니언을 처치하며 무덤을 만들고 체력을 회복하니 무덤이 쌓이지 않게 주의하세요. (Q)\'피의 갈망\'을 사용해 체력을 관리하며 요릭의 공격이 닿지 않는 거리에서 짧게 교환하는 것이 좋아요. 초반에는 무덤이 생성되는 것을 막는 데 집중하세요.', lv3: '(E)\'애도의 안개\' 표식이 남으면 소환물이 쫓아오니 구체가 날아올 때 미리 거리를 조절하세요. (W)\'망자의 진\' 벽에 갇히면 기본 공격으로 벽을 부숴 빠져나오세요. (E)\'회전 베기\'로 요릭을 타격해 분노를 수급하며 지속적인 전투를 준비해요.', lv6: '(R)\'군도의 장송곡\'으로 안개 마녀가 소환되면 요릭과 오래 싸우지 말고 주의하세요. (R)\'불사의 분노\'를 사용하여 요릭의 폭발적인 피해를 버티며 역으로 몰아붙이세요. 마녀와 망령이 포탑을 압박하지 않도록 라인을 빠르게 밀거나 정리하는 것이 중요해요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 요릭의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요릭이 (Q)\'최후의 의식\'으로 회복하는 양을 점화로 억제하며 승부를 보세요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\'으로 공격 속도를 높여 평타를 빠르게 치니 주의하세요. (E)\'불길 쇄도\' 태세의 첫 평타에 기절하므로 우디르가 다가올 때 거리 조절을 잘 하세요. (E)\'회전 베기\'로 분노를 쌓으며 기회를 보세요.', lv3: '(E)\'불길 쇄도\'의 기절은 기본 공격 시 발동하며 대상별 재사용 대기시간이 있으니, 첫 평타를 맞은 뒤에 (E)\'회전 베기\'로 진입하세요. (W)\'강철 갑옷\'의 보호막과 회복이 끝날 때까지 기다렸다가 공격하는 것이 좋아요. (W)\'조롱의 외침\'으로 우디르의 공격력을 낮춰 평타 교환에서 앞서세요.', lv6: '(R)\'날개 돋친 폭풍\'의 둔화 때문에 추격이 어려우니, 폭풍이 꺼진 뒤에 (R)\'불사의 분노\'를 켜고 진입하세요. 우디르가 (E)\'불길 쇄도\'를 재사용하면 이동 불가 효과에 면역이 되니 그동안 이동 방해를 노리지 마세요. 체력이 낮을 때 (Q)\'피의 갈망\'으로 체력을 회복하며 끈질기게 공격하세요.', item: '몰락한 왕의 검을 선택해 공격 속도와 생명력 흡수 효과로 지속적인 전투를 이어가세요. 신발은 우디르의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'강철 갑옷\'의 체력 회복 효과를 줄여서 적을 처치하세요.' },
    '우르곳': { lv1: '우르곳의 (Q)\'부식성 폭약\'이 떨어지는 곳을 피해 둔화에 걸리지 않도록 주의하며 거리를 조절하세요. 1~2레벨에는 (Q)\'피의 갈망\'의 공격력 상승 효과를 활용해 평타로 우르곳의 체력을 깎으며 압박하세요. (P)\'화염의 메아리\'로 인한 지속적인 피해를 받지 않도록 주의하며 전투를 시작하세요.', lv3: '우르곳이 (E)\'경멸\'을 사용하여 돌진하며 적을 뒤로 던지는 것을 조심해야 하니 돌진 경로를 잘 살피세요. 우르곳의 (E)\'경멸\'이 빠진 순간에 (E)\'회전 베기\'로 진입하며 (W)\'조롱의 외침\'을 써서 우르곳의 공격력을 낮추세요. 우르곳이 (W)\'심판의 원\'을 켜고 사격할 때는 거리를 두어 피해를 최소화하세요.', lv6: '우르곳의 (R)\'불사의 공포\'는 체력이 일정 수준 이하인 적을 제압해 처형할 수 있으니 섬광탄을 맞은 뒤 체력이 낮은 상태로 머물지 마세요. 제압 중에는 스킬과 스펠을 쓸 수 없으니, 섬광탄이 꽂혔다면 체력이 처형 수준까지 떨어지기 전에 거리를 벌리세요. 우르곳의 (E)\'경멸\'에 맞지 않도록 조심하며 정글러의 개입을 유도해 보세요.', item: '몰락한 왕의 검을 첫 코어로 올려서 전투 지속력을 높이세요. 신발은 우르곳의 기본 공격 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳이 (R)\'불사의 공포\'로 처형을 시도하기 전에 점화로 빠르게 피해를 입혀 마무리하세요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'로 도약하며 체력을 회복하고 (P)\'끝없는 허기\'로 낮은 체력에서 더 많이 회복하니 초반에 무리하게 붙지 마세요. 1~2레벨에는 미니언을 챙기며 거리를 조절하고 워윅의 (Q)\'야수의 송곳니\' 사거리 안으로 쉽게 들어가지 않도록 주의해요.', lv3: '워윅의 (E)\'원시의 포효\'가 켜지면 받는 피해가 줄어드니 그 효과가 끝나기 전에 (E)\'회전 베기\'로 딜교를 강요하지 마세요. 워윅과 싸울 때는 (W)\'조롱의 외침\'을 사용하여 상대의 공격력을 낮추고 도망가는 워윅의 이동 속도를 늦추는 것이 좋아요. (E)\'회전 베기\'를 맞춰 분노를 빠르게 쌓으며 싸우세요.', lv6: '워윅이 (R)\'무한의 구속\'으로 제압하면 스킬을 쓸 수 없고 정화로도 풀 수 없으니 (R)\'불사의 분노\'는 도약이 오기 전에 미리 켜 두세요. 워윅이 (W)\'피의 사냥\'으로 나를 감지하지 못하게 라인을 관리하며 정글러의 개입에 대비하세요.', item: '몰락한 왕의 검을 첫 코어로 올려 전투 지속력을 높이고 헤르메스의 발걸음을 신으세요. 헤르메스의 발걸음은 워윅의 (E)\'원시의 포효\' 공포 지속시간을 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'를 통한 체력 회복을 억제하여 킬각을 잡으세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 접근하며 체력을 회복해요. 미니언 체력이 낮은 쪽에서 떨어져 위치를 잡고, 접근하면 (E)\'회전 베기\'로 분노를 쌓으며 맞대응하세요. 초반에는 (P)\'아이오니아의 열정\' 중첩이 쌓이기 전에 짧게 교환하고 빠지는 것이 좋아요.', lv3: '(E)\'쌍검협무\'의 두 번째 칼날이 날아오는 길목을 피해 기절과 표식을 피하세요. 표식이 남으면 (Q)\'칼날 쇄도\'가 초기화되어 계속 추격당하니 주의해야 해요. 이렐리아가 (W)\'저항의 춤\'으로 물리 피해를 줄이는 동안에는 공격을 멈추고, 스킬이 끝난 뒤 (W)\'조롱의 외침\'으로 공격력을 낮추며 공격하세요.', lv6: '(R)\'선봉진격검\'의 결계 안에서는 둔화되니 무리하게 진입하지 말고 결계 밖으로 나가세요. 체력이 낮아져 공격력이 높아진 시점에 (R)\'불사의 분노\'를 켜고 (E)\'회전 베기\'로 빠르게 접근해 교환을 끝내세요. 상대의 (E)\'쌍검협무\'가 빠진 타이밍에 진입해야 기절 없이 공격을 퍼부을 수 있어요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력 비례 피해와 생명력 흡수로 버티며 싸우세요. 신발은 이렐리아의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 이렐리아의 (Q)\'칼날 쇄도\' 회복 효과를 줄여 마무리하기 편해요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\' 촉수가 있는 벽 근처에서 강하니 라인 중앙에서 싸우세요. (Q)\'촉수 강타\'의 정면 공격 범위를 피하며 (E)\'회전 베기\'로 짧게 진입했다가 빠지는 식으로 딜교환을 하세요. 1~2레벨에는 무리하게 붙기보다 미니언을 쳐서 분노를 쌓는 것이 중요해요.', lv3: '(E)\'영혼의 시험\'에 맞으면 내 영혼이 분리되니 영혼에서 너무 멀어지지 않게 주의하세요. 영혼에서 멀어지면 내가 숙주가 되어 촉수가 생기고, 일라오이가 영혼을 때리면 피해 일부가 나에게 들어와요. 일라오이가 (W)\'혹독한 가르침\'으로 도약해 붙으려 할 때 (W)\'조롱의 외침\'을 사용해 상대의 공격력을 낮추세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용하면 주변에 촉수가 많이 생겨 매우 위험하니 즉시 범위를 벗어나세요. 상대의 궁극기 효과가 끝날 때쯤 (R)\'불사의 분노\'를 켜고 진입해 끝까지 추격하며 피해를 입히세요. 라인을 당겨 정글러와 함께 (E)\'영혼의 시험\'이 빠진 틈을 노려 공격하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 일라오이에게 효과적인 피해를 주고 생명력 흡수로 유지력을 높이세요. 신발은 일라오이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력이 강한 일라오이를 상대로 빠르게 복귀해 손실을 최소화하세요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 뻗어 적을 붙잡고 둔화시키니 팔이 뻗어오는 경로에서 빠르게 벗어나세요. 미니언과 일직선으로 서 있으면 다른 대상과 함께 공중으로 띄워질 수 있으니 거리 조절에 유의하세요. (Q)\'피의 갈망\'으로 체력을 관리하며 자크가 (P)\'세포 분열\' 조각을 흡수해 회복하는 것을 방해하세요.', lv3: '(E)\'새총 발사\'는 충전 후 날아오므로 자크가 몸을 당기는 모습이 보이면 즉시 옆으로 피하세요. 자크가 (W)\'불안정 물질\'을 쓰기 위해 근접하면 (E)\'회전 베기\'로 빠르게 진입해 공격하고 다시 거리를 벌리세요. (W)\'조롱의 외침\'을 사용해 자크가 도망갈 때 둔화를 걸어 평타 공격 횟수를 늘려 분노를 쌓으세요.', lv6: '(R)\'바운스!\'는 여러 번 튀어 올라 적을 공중에 띄우므로, 공중에 뜬 동안에는 스킬을 쓸 수 없으니 주의하세요. (R)\'불사의 분노\'를 켜고 진입해 (Q)\'피의 갈망\'으로 버티며 자크의 체력을 깎으세요. 자크가 (P)\'세포 분열\'로 조각이 되어 흩어지면 (E)\'회전 베기\'를 이용해 빠르게 이동하며 조각들을 하나씩 처리하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 자크에게 효율적인 피해를 입히고 생명력 흡수를 챙기세요. 신발은 자크의 마법 피해를 줄이고 군중 제어 지속시간을 낮추는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 자크의 (P)\'세포 분열\' 회복 효과를 줄여 체력을 더 빠르게 깎을 수 있어요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하니 정면 승부는 피하세요. (P)\'전쟁 단련\' 중첩이 쌓이면 자헨의 공격력이 올라가니 짧게 치고 빠지세요. (E)\'회전 베기\'로 빠르게 접근해 평타를 치고 물러나며 분노를 쌓으세요.', lv3: '자헨이 (W)\'공포의 귀환\'으로 끌어당기려 할 때 옆으로 피해 주세요. (E)\'찬란한 쇄도\'로 들어오는 타이밍에 (W)\'조롱의 외침\'을 써서 자헨의 공격력을 낮추고, 자헨이 빠질 때 둔화로 추격하세요. (Q)\'다르킨의 글레이브\'의 재사용 효과인 공중에 띄우기에 맞지 않도록 주의하며 평타를 치세요.', lv6: '자헨이 (R)\'단호한 판결\'로 날아오르면 낙하 지점에서 빠르게 벗어나세요. 자헨의 체력이 낮을 때 (R)\'불사의 분노\'를 켜고 몰아붙이되, (P)\'전쟁 단련\'으로 부활할 수 있으니 완전히 처치될 때까지 방심하지 마세요. (Q)\'피의 갈망\'으로 체력을 관리하며 정글러가 오기 좋은 라인 상태를 유지하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력 비례 피해와 생명력 흡수로 유지력을 높이세요. 신발은 자헨의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨이 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화의 치유 감소가 효과적이에요.' },
    '잭스': { lv1: '잭스가 (Q)\'도약 공격\'으로 붙으며 (W)\'무기 강화\'를 사용하는 타이밍에 맞붙으면 피해가 커요. 1~2레벨에는 무리하게 딜교하지 말고 (E)\'회전 베기\'를 사용해 분노를 쌓으며 거리 조절을 하세요. 잭스의 공격 속도가 (P)\'가차없는 맹공\'으로 올라가기 전에 짧게 치고 빠지는 것이 좋아요.', lv3: '잭스가 (E)\'반격\'을 켜면 트린다미어의 기본 공격을 모두 피하고 기절을 걸어요. (E)\'반격\'이 지속되는 동안은 (E)\'회전 베기\'로 거리만 유지하고, 스킬이 끝난 뒤에 (W)\'조롱의 외침\'을 사용해 잭스의 공격력을 낮추며 딜교하세요. 잭스가 (Q)\'도약 공격\'으로 들어왔다가 빠질 때 (W)\'조롱의 외침\'을 쓰면 도망가는 잭스의 이동 속도를 늦출 수 있어요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용해 방어력을 높이면 정면 승부를 피하고 지속시간이 끝날 때까지 거리를 두세요. 잭스의 (E)\'반격\' 기절이 끝나고 (Q)\'도약 공격\'이 빠진 타이밍에 (R)\'불사의 분노\'를 켜고 몰아치면 킬각을 잡기 편해요. 라인을 밀어 넣고 잭스의 스킬이 빠졌을 때 정글러와 함께 압박하는 것도 좋은 방법이에요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화를 사용하면 잭스의 (Q)\'도약 공격\'을 따라잡거나 (E)\'반격\' 상황에서 거리를 조절하기 쉬워요.' },
    '제이스': { lv1: '제이스가 캐논 형태의 (Q)\'전격 폭발\'로 견제하려 하니 투사체 직선 밖에서 움직이며 체력을 관리하세요. (E)\'회전 베기\'로 빠르게 다가가 분노를 쌓고, 제이스가 해머로 (Q)\'하늘로!\'를 쓰며 도약할 때는 낙하지점을 피해 거리 조절을 하세요.', lv3: '해머 형태의 (E)\'천둥 강타\'에 밀려나면 딜교환이 끊기니, 상대가 이 스킬을 쓴 직후에 (E)\'회전 베기\'로 진입하세요. 붙은 뒤에는 (W)\'조롱의 외침\'을 사용해 제이스의 공격력을 낮추고 둔화를 걸어 추격하세요. (E)\'가속 관문\'을 통해 날아오는 (Q)\'전격 폭발\'은 피해가 크니 관문이 보이면 옆으로 피하세요.', lv6: '(R)\'불사의 분노\'를 켜고 진입하면 제이스의 폭발적인 피해를 견디며 끝까지 추격할 수 있어요. 다만 (R)\'머큐리 캐논\'으로 변환한 직후의 첫 공격은 방어력을 깎으니, 이 공격을 맞기 전에 (E)\'회전 베기\'로 거리를 좁히세요. 제이스가 (E)\'천둥 강타\'를 헛쓴 틈을 타 붙어서 교환하세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'천둥 강타\'에 밀려나더라도 다시 빠르게 접근해 압박하세요.' },
    '초가스': { lv1: '초가스는 (E)\'날카로운 가시\'로 정면에 피해와 둔화를 주니 정면에서 계속 싸우지 마세요. (Q)\'파열\'이 떨어지는 지점을 보고 범위 밖으로 벗어나며 (Q)\'피의 갈망\'으로 체력을 관리해요. 초가스가 (P)\'육식\'으로 미니언을 잡으며 회복하지 못하도록 압박을 유지하세요.', lv3: '초가스의 (W)\'흉포한 울부짖음\'에 걸리면 (Q)\'피의 갈망\'을 바로 쓸 수 없으니 원뿔 범위에 서지 마세요. (Q)\'파열\'에 맞으면 이동이 제한되므로 (E)\'회전 베기\'를 사용해 초가스의 스킬을 피하며 거리를 조절해요. 초가스의 스킬이 빠진 타이밍에 (E)\'회전 베기\'로 진입해서 공격하세요.', lv6: '초가스의 (R)\'포식\'은 큰 고정 피해를 주니 체력이 낮을 때 (R)\'불사의 분노\'를 켜서 죽지 않고 버티며 역공하세요. (W)\'흉포한 울부짖음\' 침묵을 맞기 전에 (R)\'불사의 분노\'를 미리 쓰는 것이 중요해요. 체력이 낮을 때는 (Q)\'파열\'을 조심하며 라인을 당기고 정글러의 개입을 기다려요.', item: '몰락한 왕의 검을 첫 코어로 가서 초가스의 높은 체력을 깎으세요. 신발은 초가스의 마법 피해와 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\' 회복 효과를 억제하며 킬각을 잡으세요.' },
    '카밀': { lv1: '1~2레벨에는 카밀의 (P)\'적응형 방어 체계\' 보호막이 생성될 때 무리하게 (E)\'회전 베기\'를 사용하지 마세요. 카밀이 (Q)\'정확성 프로토콜\'로 강화 공격을 하기 전에는 거리를 조절하며 파밍에 집중하세요. 카밀의 보호막이 사라지는 타이밍에 (E)\'회전 베기\'를 섞어 짧은 딜교환을 시도해요.', lv3: '카밀이 (W)\'전술적 휩쓸기\'를 사용하면 원뿔 바깥쪽 절반에 맞지 않도록 안쪽으로 붙거나 멀리 떨어지세요. (E)\'갈고리 발사\'로 벽을 타고 날아오는 카밀의 착지 지점을 예측하여 (E)\'회전 베기\'로 거리를 조절하세요. 카밀의 (E)\'갈고리 발사\'가 빠진 직후에 (E)\'회전 베기\'를 사용하여 압박을 가하세요.', lv6: '카밀이 (R)\'마법공학 최후통첩\'을 사용하면 특정 지역에 갇히게 되니 (R)\'불사의 분노\'를 사용하여 생존하며 맞서 싸우세요. 카밀이 (E)\'갈고리 발사\'로 벽을 넘어 들어오며 정글러를 부를 수 있으니 라인 옆 벽 근처에서의 싸움은 조심하세요. 카밀의 (R)\'마법공학 최후통첩\' 안에서 (Q)\'피의 갈망\'으로 체력을 유지하며 버티세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 공격 속도를 올려 주는 광전사의 군화를 맞추세요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '카사딘': { lv1: '카사딘이 (Q)\'무의 구체\'를 사용하여 보호막을 얻으며 견제할 때 무리하게 맞붙기보다 거리 조절을 하며 대응해야 해요. (Q)\'피의 갈망\'을 사용할 수 있을 만큼 체력을 관리하며 1~2레벨 구간의 마법 피해를 견뎌내고 분노를 쌓으세요.', lv3: '카사딘이 (E)\'힘의 파동\'을 사용하여 둔화를 걸면 (W)\'조롱의 외침\'으로 상대의 공격력을 낮추며 맞대응하세요. 카사딘의 (Q)\'무의 구체\'가 만든 보호막이 사라진 뒤 (E)\'회전 베기\'를 사용하여 빠르게 진입하는 것이 좋아요.', lv6: '카사딘이 (R)\'균열 이동\'을 사용하여 거리를 벌리려 하면 (R)\'불사의 분노\'를 사용하여 버티며 끝까지 추격하세요. 라인을 강하게 압박하여 카사딘이 성장에 집중하지 못하도록 만들고 정글러의 개입을 주의하며 플레이하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 선택하세요. 마법 저항력을 얻기 위해 헤르메스의 발걸음을 가고 몰락한 왕의 검의 생명력 흡수로 전투를 지속해요.', spell: '점멸과 점화를 추천해요. 점멸로 카사딘의 거리 조절에 대응하고 점화로 상대의 체력을 낮춰 킬을 노려요.' },
    '카시오페아': { lv1: '(Q)\'맹독 폭발\'에 맞으면 카시오페아의 이동 속도가 빨라지므로 거리를 유지하며 미니언을 챙기세요. 체력이 낮아지면 (Q)\'피의 갈망\'을 사용하여 체력을 회복하며 라인에서 버티는 것이 중요해요.', lv3: '카시오페아가 (W)\'독기의 늪\'을 사용하면 둔화에 걸리므로 주의하며 대응하세요. (E)\'쌍독니\'를 맞기 전에 (W)\'조롱의 외침\'을 사용하여 적의 공격력을 낮추거나 (E)\'회전 베기\'를 활용해 딜교환을 시도해요.', lv6: '카시오페아의 (R)\'석화의 응시\'를 정면으로 바라보면 기절할 수 있으니 위치 선정이 중요해요. (R)\'불사의 분노\'를 사용하여 상대의 강력한 마법 피해를 견디며 (E)\'회전 베기\'를 통해 끝까지 추격하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 헤르메스의 발걸음으로 마법 저항력을 얻고 몰락한 왕의 검으로 생명력 흡수를 챙겨 전투를 지속해요.', spell: '점멸과 점화를 선택하세요. 점화를 사용하여 카시오페아가 (E)\'쌍독니\'로 체력을 회복하는 것을 억제하며 킬을 노려요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 던져 (P)\'폭풍의 표식\'을 쌓으며 멀리서 압박해요. 표식이 쌓이기 전에 (Q)\'피의 갈망\'으로 체력을 관리하며 미니언을 챙기세요. 수리검의 궤적을 보고 옆으로 피해 주면 교전에서 앞서갈 수 있어요.', lv3: '케넨이 (E)\'번개 질주\'로 들어오면 표식이 쌓이지 않게 거리를 조절하고 (W)\'전류 방출\'의 피해를 조심하세요. 케넨의 이동기가 빠진 것을 확인했다면 (E)\'회전 베기\'를 사용하여 빠르게 접근해 공격하세요. (P)\'폭풍의 표식\'이 세 번 쌓여 기절하기 전에 교전을 마무리하는 것이 좋아요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용하면 주변 모든 적에게 피해를 주니 무리하게 들어가지 마세요. 케넨의 궁극기가 끝난 뒤 (R)\'불사의 분노\'를 켜고 (E)\'회전 베기\'로 진입해 몰아붙이세요. 기절에 걸리면 스킬을 쓸 수 없으니 정글러의 위치를 확인하며 싸우세요.', item: '첫 코어로 몰락한 왕의 검을 가서 전투 지속력을 높이세요. 신발은 케넨의 마법 피해와 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 케넨의 스킬 범위를 벗어나며 빠르게 접근하거나 도망치세요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'으로 레벨이 오를수록 강해지니 초반에 적극적으로 압박하세요. (Q)\'광휘의 일격\'에 맞아 이동 속도와 방어력, 마법 저항력이 감소하지 않도록 거리를 잘 유지해야 해요. (Q)\'피의 갈망\'으로 체력을 관리하며 주도권을 가져오세요.', lv3: '케일이 (E)\'화염주문검\'을 사용하여 잃은 체력에 비례한 피해를 입히기 전에 (W)\'조롱의 외침\'으로 이동 속도를 늦추며 접근하세요. 케일이 (W)\'천상의 축복\'을 사용해 체력을 회복하며 도망칠 때 (E)\'회전 베기\'로 빠르게 따라붙어야 해요. (Q)\'피의 갈망\'을 적절히 사용하여 딜교환을 이어가세요.', lv6: '케일이 (R)\'신성한 심판\'을 사용하여 자신을 무적 상태로 만들면 공격이 들어가지 않으니 주의하세요. (R)\'불사의 분노\'를 사용하여 케일의 폭발적인 마법 피해를 버텨내며 끝까지 추격해야 해요. 케일이 성장을 마치기 전에 정글러와 함께 빠르게 처치하는 것이 좋아요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 케일의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 케일의 체력 회복 효과를 감소시키고 빠르게 킬을 노리세요.' },
    '코그모': { lv1: '코그모의 (Q)\'부식성 침\' 사거리가 길어 미니언 뒤에 숨어 피해를 최소화하며 경험치를 꾸준히 챙겨야 해요. (Q)\'피의 갈망\'을 적절히 사용하여 체력을 회복하며 성장에 적극적으로 집중하세요.', lv3: '코그모가 (W)\'생체마법 폭격\'으로 사거리를 늘리면 접근이 어려우니 주의해야 해요. (E)\'회전 베기\'로 진입할 때 코그모의 (E)\'공허의 분비물\'이 남긴 둔화 흔적을 밟지 않도록 정말로 조심하세요.', lv6: '(R)\'불사의 분노\'를 켜고 코그모의 (R)\'살아있는 곡사포\' 피해를 견디며 끈질기게 추격하세요. (W)\'조롱의 외침\'을 맞춰 공격력을 낮춘 뒤 빠르게 처치하고 라인을 강하게 압박하세요.', item: '코그모의 마법 피해에 대항하기 위해 헤르메스의 발걸음을 가고 전투 지속력을 위해 몰락한 왕의 검을 가요. 아이템의 생명력 흡수로 버티며 싸우는 것이 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 이동 속도를 높여 코그모와의 거리를 좁히고 점멸로 변수를 만들어 보세요.' },
    '코르키': { lv1: '(Q)\'인광탄\'은 범위 공격이라 미니언 뒤에 숨어도 맞으니 움직이며 피하세요. 체력이 낮아지면 (Q)\'피의 갈망\'으로 체력을 회복하며 버티는 것이 중요해요. 1~2레벨 구간에는 무리하게 진입하지 말고 분노를 쌓으며 기회를 기다리세요.', lv3: '(E)\'회전 베기\'로 빠르게 진입하여 딜교환을 시도하세요. 상대가 (W)\'발키리\'로 도망치려 할 때 (W)\'조롱의 외침\'을 사용해 이동 속도를 늦추고 추격하세요. (E)\'개틀링 건\'에 맞으면 방어력이 낮아져 더 아프게 맞으니 주의하세요.', lv6: '(R)\'불사의 분노\'를 켜고 (R)\'미사일 폭격\'의 피해를 무시하며 끝까지 밀어붙이세요. (W)\'발키리\'가 빠진 타이밍에 (E)\'회전 베기\'로 진입하면 킬을 따내기 편해요. 라인을 밀고 정글러를 불러 함께 압박하는 것이 효율적이에요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 가요. 헤르메스의 발걸음은 마법 저항력을 제공하며 몰락한 왕의 검은 공격 속도와 생명력 흡수로 유지력을 높여줘요.', spell: '점멸과 유체화를 추천해요. (W)\'발키리\'를 사용해 거리를 벌리는 코르키를 끝까지 추격하기 위해서예요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 통해 첫 평타로 강한 피해를 주며 견제해요. 1~2레벨에는 퀸의 평타 거리를 조심하며 (Q)\'피의 갈망\'으로 체력을 관리하고 성장에 집중하세요. (E)\'회전 베기\'로 미니언을 챙기며 퀸의 접근을 경계하세요.', lv3: '퀸이 (Q)\'실명 공격\'을 사용해 시야를 좁히면 위치를 놓치지 않게 주의하세요. 퀸이 (E)\'공중제비\'를 쓰고 뒤로 물러날 때 (E)\'회전 베기\'로 거리를 좁히며 (W)\'조롱의 외침\'을 맞춰주세요. 퀸의 공격력을 낮추면 더 적극적으로 딜교환을 할 수 있어요.', lv6: '퀸이 (R)\'후방 지원\'을 사용해 다른 라인으로 이동하면 빠르게 라인을 밀어 포탑을 압박하세요. 퀸의 폭발적인 공격에 (R)\'불사의 분노\'를 사용하여 버티며 반격을 준비해요. (E)\'회전 베기\'를 사용해 퀸을 끝까지 추격하며 킬각을 노리세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 퀸의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 퀸의 견제를 이겨내며 빠르게 접근하세요.' },
    '크산테': { lv1: '크산테가 (Q)\'엔토포 타격\'으로 둔화를 걸며 견제할 때 거리를 조절하며 미니언을 챙기세요. (E)\'회전 베기\'를 활용해 빠르게 웨이브를 정리하며 상대가 (Q)\'엔토포 타격\' 중첩을 쌓지 못하도록 압박해요.', lv3: '크산테가 (W)\'길을 여는 자\'를 충전하며 돌진할 때는 저지 불가 상태이므로 옆으로 비켜서서 밀려나고 기절하는 것을 피하세요. 상대의 (E)\'발놀림\' 보호막이 소모된 시점에 (E)\'회전 베기\'로 붙어 (W)\'조롱의 외침\'과 함께 딜교환을 해요.', lv6: '크산테가 (R)\'총공세\'를 사용하여 방어력이 줄어든 상태로 몰아칠 때 (R)\'불사의 분노\'를 켜고 버티며 맞대응하세요. 상대가 궁극기로 벽을 넘겨 멀리 보낼 수 있으니 정글러의 위치를 확인하며 위험한 곳으로 끌려가지 않도록 주의해요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 공격 속도를 제공하는 광전사의 군화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해는 (R)\'총공세\'로 방어력이 줄어든 크산테를 마무리하기 좋아요.' },
    '클레드': { lv1: '클레드는 (Q)\'덫날리기\'로 챔피언을 붙잡아 끌어당기며 초반 압박을 해요. 덫에 맞았다면 클레드에게서 빠르게 멀어져 끌려가지 않도록 주의하고 평타로 분노를 쌓으세요. (Q)\'피의 갈망\'으로 체력을 관리하며 스칼의 체력을 깎는 짧은 딜교환을 반복하세요.', lv3: '클레드가 (E)\'이랴!\'로 돌진해 들어올 때 (W)\'조롱의 외침\'을 사용해 공격력을 낮추고, 클레드가 빠질 때 둔화로 추격하세요. (W)\'버럭버럭\'이 켜진 동안은 빠른 공격 속도로 인해 위험하니 뒤로 빠졌다가 스킬이 끝난 뒤 (E)\'회전 베기\'로 진입하세요. 상대의 (Q)\'덫날리기\'가 빗나간 타이밍에 진입해 공격하는 것이 좋아요.', lv6: '(R)\'돌겨어어억!!!\'은 보호막을 쓰고 돌진하며 마지막에 밀어내니 옆으로 피하며 거리 조절을 하세요. 클레드가 스칼에서 내려 챔피언 피해량이 줄어든 상태라면 (R)\'불사의 분노\'를 켜고 끝까지 추격해 처치하세요. 정글러가 올 때 스칼이 없는 클레드는 쉽게 잡히니 (E)\'회전 베기\'로 빠르게 접근해 마무리하세요.', item: '굶주린 히드라를 첫 코어로 선택해 생명력 흡수로 버티며 라인 푸시력을 챙기세요. 신발은 클레드의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 클레드가 스칼에서 내렸을 때 점화의 추가 피해로 빠르게 처치해 다시 스칼을 타지 못하게 하세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 처음 맞는 유닛에 피해와 둔화를 주니 미니언 뒤에 서서 막아내세요. (E)\'회전 베기\'로 분노를 쌓으며 짧게 교전하되 (P)\'절대 미각\' 중첩이 세 번 쌓이기 전에 빠지세요. 중첩이 다 쌓이면 다음 (Q)\'혀 채찍\'에 기절하니 거리 조절이 중요해요.', lv3: '(W)\'심연 잠수\'는 지정한 장소에서 적을 공중에 띄우니 표시가 보이면 빠르게 범위 밖으로 벗어나세요. (E)\'두꺼운 피부\' 보호막이 켜진 동안은 딜을 아꼈다가 보호막이 사라진 뒤에 공격하세요. (W)\'조롱의 외침\'으로 상대 공격력을 낮추고 둔화를 걸어 추격하며 짧은 딜교환을 반복하세요.', lv6: '(P)\'절대 미각\' 중첩이 세 번 쌓인 상태에서 (R)\'집어삼키기\'에 먹히면 큰 피해를 입으니 주의하세요. (R)\'불사의 분노\'를 켜서 죽지 않는 상태를 만든 뒤 (Q)\'피의 갈망\'으로 체력을 회복하며 끝까지 밀어붙이세요. 상대의 (Q)\'혀 채찍\' 기절 타이밍을 피하며 공격을 이어가세요.', item: '체력이 높은 상대에게 효율적인 몰락한 왕의 검을 첫 코어로 선택하세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'를 통한 체력 회복을 억제하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치고 둔화를 걸어 초반 평타 교환이 강해요. (E)\'회전 베기\'로 분노를 쌓으며 짧게 딜교환하고 (Q)\'깨물기\'를 맞은 뒤에는 무리하게 싸우지 말고 빠지세요. (P)\'헌납\'으로 유닛 처치 시 체력을 회복하니 미니언이 많은 곳에서의 장기전은 피하세요.', lv3: '트런들이 (W)\'얼음 왕국\'을 깔면 공격 속도와 회복량이 늘어나니 영역 밖으로 빠르게 벗어나세요. (E)\'얼음 기둥\'에 막히면 접근이 어려우므로 기둥이 빠진 것을 확인하고 (E)\'회전 베기\'로 진입하세요. (W)\'조롱의 외침\'을 사용해 상대의 공격력을 낮추고 적이 도망갈 때 둔화를 걸어 추격하세요.', lv6: '트런들이 (R)\'진압\'을 쓰면 방어력과 체력을 훔치므로 즉시 거리를 벌려 효과가 끝나길 기다리세요. (R)\'진압\'의 지속 시간이 끝난 뒤 (R)\'불사의 분노\'를 켜고 공격적으로 들어가면 처치하기 편해요. (E)\'얼음 기둥\'으로 도주로를 차단하고 정글러를 부르는 플레이가 잦으니 좁은 길목을 피하세요.', item: '굶주린 히드라를 첫 코어로 선택해 라인 푸시력과 생명력 흡수로 유지력을 챙기세요. 신발은 트런들의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'헌납\'과 (W)\'얼음 왕국\'으로 인한 강력한 체력 회복을 점화의 치유 감소로 억제하세요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'를 사용해 지속 피해를 주니 무리하게 진입하지 말고 체력을 관리하세요. 수풀에서는 (P)\'유격 전투\'로 투명해질 수 있으니 항상 주변 시야를 확보해야 해요. 체력이 낮아지면 (Q)\'피의 갈망\'을 사용해 체력을 회복하며 버티세요.', lv3: '티모의 (Q)\'실명 다트\'를 맞으면 평타가 빗나가니 스킬이 빠진 것을 확인하고 진입하세요. (E)\'회전 베기\'로 붙은 뒤 (W)\'조롱의 외침\'을 사용해 티모의 공격력을 낮추고 추격하세요. 티모가 (W)\'신속한 이동\'으로 거리를 벌리려 해도 끈질기게 따라붙어야 해요.', lv6: '라인에 깔린 (R)\'유독성 함정\'을 밟지 않도록 주의하며 티모의 위치를 확인하세요. 교전 중 체력이 낮아지면 (R)\'불사의 분노\'를 켜서 죽지 않고 끝까지 공격을 이어가세요. (R)\'유독성 함정\'의 둔화가 있더라도 (R)\'불사의 분노\'를 활용해 압박을 계속하세요.', item: '몰락한 왕의 검을 코어 아이템으로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 마법 피해를 줄이기 위해 헤르메스의 발걸음을 구매하세요.', spell: '점멸과 유체화를 추천해요. 유체화로 (W)\'신속한 이동\'을 쓰는 티모를 빠르게 추격할 수 있어요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 통해 멀리서 견제하며 초반에 강한 모습을 보여요. (P)\'필멸자의 의지\'로 강화된 스킬을 맞지 않도록 주의하며 (E)\'회전 베기\'로 미니언을 챙기세요. 상대가 (Q)\'혜성의 창\'을 던지려고 하면 거리를 조절하며 짧게 평타로 교환해요.', lv3: '판테온이 (E)\'방패 돌격\'을 사용하면 정면의 피해를 받지 않으니 옆으로 돌아가서 공격하세요. (W)\'방호의 도약\'에 기절하면 스킬을 쓸 수 없으니 상대의 돌진이 빠진 것을 보고 (E)\'회전 베기\'로 진입해요. 판테온이 도망가려고 등을 돌리면 (W)\'조롱의 외침\'을 사용하여 이동 속도를 늦추세요.', lv6: '판테온이 (R)\'거대 유성\'을 사용해 공중으로 떠오르면 착지 지점을 확인하고 빠르게 피하세요. 판테온의 폭발적인 피해가 들어올 때 (R)\'불사의 분노\'를 사용하여 버티며 맞딜을 시도해요. 판테온이 궁극기를 사용해 다른 라인에 개입하면 라인을 관리하며 다음 기회를 기다리세요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수를 챙기세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 (Q)\'혜성의 창\'을 옆으로 피하면서 판테온에게 빠르게 따라붙으세요.' },
    '피들스틱': { lv1: '첫 웨이브부터 (E)\'회전 베기\'를 사용해 빠르게 접근하며 압박하세요. (E)\'수확\'의 중심에 맞으면 침묵에 걸리니 외곽 부분을 맞으며 진입하는 것이 중요해요. (Q)\'공포\'를 피하기 위해 상대가 시야 밖으로 숨지 못하게 계속 밀어붙이세요.', lv3: '(E)\'회전 베기\'로 빠르게 붙은 뒤 (W)\'조롱의 외침\'을 사용해 도망가는 상대의 이동 속도를 늦추세요. 상대가 (W)\'풍작\'을 사용해 체력을 흡수하려 하면 즉시 범위 밖으로 벗어나 피해를 최소화하세요. 딜교환 이후에는 (Q)\'피의 갈망\'으로 체력을 회복하며 다음 기회를 노리세요.', lv6: '(R)\'까마귀 폭풍\'으로 기습당해 체력이 급격히 낮아지면 즉시 (R)\'불사의 분노\'를 켜서 생존하세요. 궁극기 지속 시간 동안 (E)\'회전 베기\'로 끝까지 추격해 상대를 처치하세요. 시야 밖에서 들어오는 (Q)\'공포\' 기습을 조심하며 라인을 적절히 유지하세요.', item: '헤르메스의 발걸음과 마법사의 최후를 추천해요. 강인함으로 (Q)\'공포\'와 (E)\'수확\'의 군중 제어 지속 시간을 줄이고 마법 저항력으로 피해를 버텨야 해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (W)\'풍작\'의 체력 회복량을 줄이고 확실하게 처치하기 위해서예요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 빠르게 접근하고 (E)\'대가의 검술\'로 강력한 치명타를 노리니 1~2레벨에는 무리하게 붙지 마세요. (E)\'회전 베기\'로 분노를 쌓으며 미니언을 정리하고, (P)\'치명적인 검무\'의 급소가 노출되지 않게 계속 움직이며 거리를 조절해요.', lv3: '피오라가 (W)\'응수\'를 사용해 공격을 막아내면 둔화나 기절에 걸리니, (W)\'응수\'가 빠진 것을 확인한 뒤 (E)\'회전 베기\'로 진입하세요. (W)\'조롱의 외침\'으로 피오라의 공격력을 낮추면 (E)\'대가의 검술\'의 피해량을 줄일 수 있어 교환 과정이 편해져요.', lv6: '피오라가 (R)\'대결투\'로 급소를 모두 드러내면 고정 피해가 크니, 최대한 빠르게 움직여 급소를 맞히지 못하게 하세요. 체력이 낮아졌을 때 (R)\'불사의 분노\'를 켜고 공격적으로 밀어붙이면 피오라의 폭발적인 피해를 견디며 처치할 수 있어요.', item: '삼위일체를 첫 코어로 선택해 공격 속도와 체력을 챙겨 지속 싸움 능력을 높이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 피오라는 (P)\'치명적인 검무\'와 (R)\'대결투\'로 체력을 회복하므로 점화의 치유 감소 효과로 이를 억제해야 해요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 압박하며 포탑 주변에서 이동 속도가 올라요. 1~2레벨에는 무리하게 진입하지 말고 포탑 사거리를 피해 막타를 챙기세요. 하이머딩거가 포탑 설치 후 방심할 때 (E)\'회전 베기\'로 빠르게 접근해 평타를 입히세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 중심부에 맞으면 기절하니 수류탄이 날아오는 방향을 보고 옆으로 피하세요. (W)\'마법공학 초소형 로켓\'의 피해를 최소화하며 다가간 뒤 (W)\'조롱의 외침\'을 써서 상대 공격력을 낮추고 이동 속도를 늦추세요. 상대의 수류탄이 빗나간 순간 (E)\'회전 베기\'로 진입해 강하게 공격하세요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 수류탄을 던지면 기절 범위가 넓어지니 주의하세요. (R)\'불사의 분노\'를 켜고 진입하면 상대의 폭발적인 피해를 무시하며 끝까지 추격할 수 있어요. (Q)\'피의 갈망\'으로 체력을 회복하며 포탑들을 빠르게 제거하고 하이머딩거 본체를 공격하세요.', item: '맬모셔스의 아귀를 가서 마법 저항력을 높이고 생명선 보호막으로 상대의 폭딜을 견디세요. 신발은 (E)\'CH-2 전자폭풍 수류탄\'의 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 증가와 유닛 충돌 무시로 거리를 빠르게 좁혀 공격하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_tryndamere);
if (typeof module !== 'undefined') module.exports = top_tryndamere;
